var SRC={"id":"tua24","tag":"UA24","name":"Unearthed Arcana (2024 rules)","desc":"22 subclasses, 24 feats, 1 spells, 4 species.","feats":[],"spells":[],"rows":[],"subs":["Path of Lament","Primordial Patron","Warrior of Venom","Faerzress Sorcery","Freedom Domain","House Agent","Imaskarcanist","Path of Unlight","Circle of the Titan","Demonic Sorcery","Hell Knight","Magic Stealer","Oath of the Spellguard","Warrior of Intoxication","Purple Dragon Knight","Tattooed Warrior","Ancestral Sorcery","Hexblade Patron","Circle of Preservation","Defiled Sorcery","Gladiator","Sorcerer-King Patron"],"tp":1,"pub":"Wizards of the Coast","ed":"2024","classes":[]};
var D=[{"alt":[],"cls":"Barbarian","name":"Path of Lament","src":"tua24","arr":[[3,"Banshee's Wail","When you start your Rage, or as a Bonus Action while it lasts, you can wail. Each creature of your choice in a 30-foot Emanation makes a Constitution save (DC 8 + Constitution modifier + Proficiency Bonus). A failure takes Psychic damage and is Deafened for 1 minute. A success takes half damage. The damage is a number of d12 equal to your Rage Damage bonus. You can use this a number of times equal to your Constitution modifier (min 1), regaining all uses after a Long Rest, or by spending a Rage use (no action)."],[6,"Commune with the Dead","You can cast Speak with Dead as a Ritual only. Wisdom is your spellcasting ability for it."],[6,"Horrifying Strike","Once per turn, when you hit with a Strength-based attack roll while Raging, you can try to horrify the target. It makes a Wisdom save (DC 8 + Constitution modifier + Proficiency Bonus) or is Frightened until the start of your next turn."],[10,"Otherworldly Anguish","Deathly Wail: a target that fails its save against Banshee's Wail and has Hit Points equal to or below twice your Barbarian level drops to 0 Hit Points instead of taking damage. Impenetrable Sorrow: you can't be possessed. Resistance: while Raging you have Resistance to Cold and Necrotic damage."],[14,"Sorrow Form","When you start your Rage you can take on an undead form for 1 minute or until you drop to 0 Hit Points. You can do this once per Long Rest. Immunities: you have Immunity to Charmed and Frightened, any such condition on you ends, and you can't gain Exhaustion. Life-Draining Strike: a creature that fails its save against Horrifying Strike takes 2d10 Necrotic damage and you regain Hit Points equal to the damage. Undead: your creature type is Undead."]],"full":{"Path of Lament|Banshee's Wail":"When you start your Rage, or as a Bonus Action while it lasts, you can wail. Each creature of your choice in a 30-foot Emanation makes a Constitution save (DC 8 + Constitution modifier + Proficiency Bonus). A failure takes Psychic damage and is Deafened for 1 minute. A success takes half damage. The damage is a number of d12 equal to your Rage Damage bonus. You can use this a number of times equal to your Constitution modifier (min 1), regaining all uses after a Long Rest, or by spending a Rage use (no action).","Path of Lament|Commune with the Dead":"You can cast Speak with Dead as a Ritual only. Wisdom is your spellcasting ability for it.","Path of Lament|Horrifying Strike":"Once per turn, when you hit with a Strength-based attack roll while Raging, you can try to horrify the target. It makes a Wisdom save (DC 8 + Constitution modifier + Proficiency Bonus) or is Frightened until the start of your next turn.","Path of Lament|Otherworldly Anguish":"Deathly Wail: a target that fails its save against Banshee's Wail and has Hit Points equal to or below twice your Barbarian level drops to 0 Hit Points instead of taking damage. Impenetrable Sorrow: you can't be possessed. Resistance: while Raging you have Resistance to Cold and Necrotic damage.","Path of Lament|Sorrow Form":"When you start your Rage you can take on an undead form for 1 minute or until you drop to 0 Hit Points. You can do this once per Long Rest. Immunities: you have Immunity to Charmed and Frightened, any such condition on you ends, and you can't gain Exhaustion. Life-Draining Strike: a creature that fails its save against Horrifying Strike takes 2d10 Necrotic damage and you regain Hit Points equal to the damage. Undead: your creature type is Undead."},"auto":[],"lu":[{"src":"sub","owner":"Path of Lament","feature":"Banshee's Wail","n":"Banshee's Wail","lvl":3,"max":"mod:CON","reset":"long","tag":"Reset by a Rage use"},{"src":"sub","owner":"Path of Lament","feature":"Sorrow Form","n":"Sorrow Form","lvl":14,"max":1,"reset":"long","tag":"When you Rage"}],"acts":{"sub|Path of Lament|Banshee's Wail":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[10,"Otherworldly Anguish",{"notes":[["Note","Otherworldly Anguish: while Raging, Resistance to Cold and Necrotic damage. Can't be possessed"]]}],[14,"Sorrow Form",{"condImm":["Charmed","Frightened"],"notes":[["Note","Sorrow Form: Undead creature type, no Exhaustion, for 1 minute"]]}]],"spab":"WIS"},{"alt":[],"cls":"Warlock","name":"Primordial Patron","src":"tua24","arr":[[3,"Elemental Node","Pick an element: Air (Thunder), Earth (Acid), Fire (Fire), or Water (Cold). It sets the damage type of several features, and you can change it whenever you gain a level. Magic action: create a 5-foot-radius Sphere of elemental magic centered on a point you see within 60 feet. On later turns you can move it up to 30 feet as a Bonus Action. Each other creature in the node makes a Dexterity save against your spell save DC when it appears, when it moves into a creature's space, and when a creature enters or ends its turn there (once per turn per creature). A failure takes 1d6 damage of your element's type, a success takes half. It lasts 1 minute, until you dismiss it (no action), or until you make a new node. You can't make one again until a Short or Long Rest, or until you spend a Pact Magic slot (no action). Damage becomes 2d6 at Warlock level 6 and 3d6 at 14."],[3,"Elemental Spells","Always prepared from the listed Warlock levels: 3 Chromatic Orb, Darkvision. 5 Elemental Weapon. 7 Summon Elemental. 9 Commune with Nature. Plus your element's spells. Air: 3 Feather Fall, Shatter. 5 Fly. 7 Freedom of Movement. 9 Steel Wind Strike. Earth: 3 Entangle, Knock. 5 Plant Growth. 7 Vitriolic Sphere. 9 Wall of Stone. Fire: 3 Burning Hands, Heat Metal. 5 Fireball. 7 Wall of Fire. 9 Flame Strike. Water: 3 Alter Self, Ice Knife. 5 Water Walk. 7 Control Water. 9 Cone of Cold."],[6,"Elemental Haven","Elemental Protection: while you are in your node you gain a bonus to AC equal to your Charisma modifier (min 1). Elemental Teleport: as a Bonus Action, teleport into your node or the nearest free space within 5 feet of it. You can do this a number of times equal to your Charisma modifier (min 1), regaining all uses after a Long Rest."],[10,"Primeval Protection","Elemental Fortitude: you have Resistance to your element's damage type, and Immunity to it while in your node. Node Improvement: your node becomes a 10-foot-radius Sphere."],[14,"Elemental Harbinger","Elemental Vortex: when you spend a Pact Magic slot while in your node, you can pull one creature you choose within 30 feet of it. It makes a Strength save or is pulled up to 15 feet toward the node's center. Node Improvement: the node lasts up to 1 hour. Primordial Herald: while in the node you can cast Planar Ally without a slot, naming your patron. After you do this you can't do it again until you finish 2d4 Long Rests."]],"full":{"Primordial Patron|Elemental Node":"Pick an element: Air (Thunder), Earth (Acid), Fire (Fire), or Water (Cold). It sets the damage type of several features, and you can change it whenever you gain a level. Magic action: create a 5-foot-radius Sphere of elemental magic centered on a point you see within 60 feet. On later turns you can move it up to 30 feet as a Bonus Action. Each other creature in the node makes a Dexterity save against your spell save DC when it appears, when it moves into a creature's space, and when a creature enters or ends its turn there (once per turn per creature). A failure takes 1d6 damage of your element's type, a success takes half. It lasts 1 minute, until you dismiss it (no action), or until you make a new node. You can't make one again until a Short or Long Rest, or until you spend a Pact Magic slot (no action). Damage becomes 2d6 at Warlock level 6 and 3d6 at 14.","Primordial Patron|Elemental Spells":"Always prepared from the listed Warlock levels: 3 Chromatic Orb, Darkvision. 5 Elemental Weapon. 7 Summon Elemental. 9 Commune with Nature. Plus your element's spells. Air: 3 Feather Fall, Shatter. 5 Fly. 7 Freedom of Movement. 9 Steel Wind Strike. Earth: 3 Entangle, Knock. 5 Plant Growth. 7 Vitriolic Sphere. 9 Wall of Stone. Fire: 3 Burning Hands, Heat Metal. 5 Fireball. 7 Wall of Fire. 9 Flame Strike. Water: 3 Alter Self, Ice Knife. 5 Water Walk. 7 Control Water. 9 Cone of Cold.","Primordial Patron|Elemental Haven":"Elemental Protection: while you are in your node you gain a bonus to AC equal to your Charisma modifier (min 1). Elemental Teleport: as a Bonus Action, teleport into your node or the nearest free space within 5 feet of it. You can do this a number of times equal to your Charisma modifier (min 1), regaining all uses after a Long Rest.","Primordial Patron|Primeval Protection":"Elemental Fortitude: you have Resistance to your element's damage type, and Immunity to it while in your node. Node Improvement: your node becomes a 10-foot-radius Sphere.","Primordial Patron|Elemental Harbinger":"Elemental Vortex: when you spend a Pact Magic slot while in your node, you can pull one creature you choose within 30 feet of it. It makes a Strength save or is pulled up to 15 feet toward the node's center. Node Improvement: the node lasts up to 1 hour. Primordial Herald: while in the node you can cast Planar Ally without a slot, naming your patron. After you do this you can't do it again until you finish 2d4 Long Rests."},"auto":[[3,"Chromatic Orb,Darkvision"],[5,"Elemental Weapon"],[7,"Summon Elemental"],[9,"Commune With Nature"]],"lu":[{"src":"sub","owner":"Primordial Patron","feature":"Elemental Node","n":"Elemental Node","lvl":3,"max":1,"reset":"short","tag":"Reset by a Pact Magic slot"},{"src":"sub","owner":"Primordial Patron","feature":"Elemental Haven","n":"Elemental Teleport","lvl":6,"max":"mod:CHA","reset":"long","tag":"Bonus Action"},{"src":"sub","owner":"Primordial Patron","feature":"Elemental Harbinger","n":"Primordial Herald (Planar Ally)","lvl":14,"max":1,"reset":"none","tag":"Available again after 2d4 Long Rests"}],"acts":{"sub|Primordial Patron|Elemental Node":[["action",""]],"sub|Primordial Patron|Elemental Haven":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[6,"Elemental Haven",{"notes":[["Note","Elemental Protection: +Charisma modifier (min +1) AC while in your Elemental Node"]]}],[10,"Primeval Protection",{"notes":[["Note","Elemental Fortitude: Resistance to your element's damage type (Air Thunder, Earth Acid, Fire Fire, Water Cold). Immunity while in your node"]]}]],"spab":"CHA"},{"alt":[],"cls":"Monk","name":"Warrior of Venom","src":"tua24","arr":[[3,"Envenom Weapon","At the start of your turn, spend 1 Focus Point to coat one Monk weapon you hold with a toxin from your blood. A creature damaged by it suffers one effect you chose when applying it. Slowing Toxin: until the start of your next turn its Speed is halved, it can't take Reactions, and it takes an action or a Bonus Action on its turn, not both. Venom: it takes Poison damage equal to two rolls of your Martial Arts die. The toxin lasts 1 minute or until a creature is damaged by the weapon."],[3,"Potent Arsenal","You gain a Poisoner's Kit and proficiency with it. You can make a Basic Poison in 1 day (8 hours of work). When you deal Poison damage with a Monk feature or Monk weapon, you can change it to Acid damage."],[6,"Toxic Touch","Magic action, spend 1 Focus Point: apply a toxin to a creature you touch. It makes a Constitution save. On a failure it is Poisoned for 1 minute and you choose one effect while it is Poisoned. Intoxicant: it is Charmed until the duration ends or you or your allies damage it. Sedative: it falls asleep and is Unconscious, and another creature can wake it with an action. Truth Serum: it can't knowingly lie."],[11,"Toxic Blood","When a creature hits you with a melee attack roll, the attacker takes 1d6 Poison damage. While you are Bloodied it takes one roll of your Martial Arts die instead."],[11,"Toxin Refiner","You have Immunity to Poison damage. When you are subjected to Poison damage, your Envenom Weapon options each deal extra Poison damage equal to one roll of your Martial Arts die, and you can't gain this benefit again until the end of your next turn. When you ingest a poison, you regain Hit Points equal to one roll of your Martial Arts die."],[17,"Hallucinogenic Breath","When you take the Attack action, spend 2 Focus Points and replace one attack with a breath of vapors at a creature you see within 30 feet. It makes a Constitution save. A failure takes Poison damage equal to three rolls of your Martial Arts die and is Frightened for 1 minute or until it takes damage. While Frightened it must Dash away from you by the safest route each turn if it can. A success takes half damage."]],"full":{"Warrior of Venom|Envenom Weapon":"At the start of your turn, spend 1 Focus Point to coat one Monk weapon you hold with a toxin from your blood. A creature damaged by it suffers one effect you chose when applying it. Slowing Toxin: until the start of your next turn its Speed is halved, it can't take Reactions, and it takes an action or a Bonus Action on its turn, not both. Venom: it takes Poison damage equal to two rolls of your Martial Arts die. The toxin lasts 1 minute or until a creature is damaged by the weapon.","Warrior of Venom|Potent Arsenal":"You gain a Poisoner's Kit and proficiency with it. You can make a Basic Poison in 1 day (8 hours of work). When you deal Poison damage with a Monk feature or Monk weapon, you can change it to Acid damage.","Warrior of Venom|Toxic Touch":"Magic action, spend 1 Focus Point: apply a toxin to a creature you touch. It makes a Constitution save. On a failure it is Poisoned for 1 minute and you choose one effect while it is Poisoned. Intoxicant: it is Charmed until the duration ends or you or your allies damage it. Sedative: it falls asleep and is Unconscious, and another creature can wake it with an action. Truth Serum: it can't knowingly lie.","Warrior of Venom|Toxic Blood":"When a creature hits you with a melee attack roll, the attacker takes 1d6 Poison damage. While you are Bloodied it takes one roll of your Martial Arts die instead.","Warrior of Venom|Toxin Refiner":"You have Immunity to Poison damage. When you are subjected to Poison damage, your Envenom Weapon options each deal extra Poison damage equal to one roll of your Martial Arts die, and you can't gain this benefit again until the end of your next turn. When you ingest a poison, you regain Hit Points equal to one roll of your Martial Arts die.","Warrior of Venom|Hallucinogenic Breath":"When you take the Attack action, spend 2 Focus Points and replace one attack with a breath of vapors at a creature you see within 30 feet. It makes a Constitution save. A failure takes Poison damage equal to three rolls of your Martial Arts die and is Frightened for 1 minute or until it takes damage. While Frightened it must Dash away from you by the safest route each turn if it can. A success takes half damage."},"auto":[],"lu":[],"acts":{"sub|Warrior of Venom|Toxic Touch":[["action",""]],"sub|Warrior of Venom|Hallucinogenic Breath":[["other","","Hallucinogenic Breath"]]},"cantrips":[],"pick":[],"fx":[[3,"Potent Arsenal",{"notes":[["Note","Potent Arsenal: Poisoner's Kit proficiency. Monk Poison damage can become Acid"]]}],[11,"Toxin Refiner",{"imm":["Poison"]}]],"spab":"WIS"},{"alt":[],"cls":"Sorcerer","name":"Faerzress Sorcery","src":"tua24","arr":[[3,"Faerzress Effects","Faerzress is magical radiation. Within an area it fills: creatures automatically pass saves against Divination effects. Magical sensors and invisible eyes, such as from Clairvoyance or Arcane Eye, can't enter. A creature teleporting 1 mile or more can't teleport into or out of the area. The area is lit with Dim Light, and creatures using Darkvision there see in color and have Advantage on Wisdom (Perception) checks that rely on sight."],[3,"Faerzress Side Effects","Roll on or choose from the Faerzress Side Effects table to decide what odd effect the radiation you give off has on your surroundings."],[3,"Faerzress Spells","Spells always prepared from the listed Sorcerer levels: 3 Faerie Fire, Magic Weapon, Misty Step, Witch Bolt. 5 Nondetection, Sending. 7 Arcane Eye, Stone Shape. 9 Passwall, Scrying."],[3,"Faerzress Zone","Magic action, spend 3 Sorcery Points: fill an area within 120 feet, no larger than a 40-foot Cube, with faerzress for 24 hours. Filling the same area every day for 365 days makes it permanent."],[3,"Immunity to Faerzress","You ignore faerzress's harmful effects. Creatures in faerzress don't automatically pass saves against your Divination spells. Sensors and eyes from your spells can enter faerzress. When you teleport yourself or others, you can enter or leave faerzress at any distance."],[6,"Faerzress Affinity","You have Resistance to Lightning damage and Darkvision 60 feet (or +30 feet if you have it). You see color in Darkness, and have Advantage on Wisdom (Perception) checks to see in Dim Light or Darkness. Your Immunity to Faerzress also covers allies within 30 feet of you."],[14,"Faerzress Spell","When creatures fail a save against a spell you cast, you can spend 1 Sorcery Point to lace one of them with faerzress for 1 minute. It can't teleport, can't cast Divination spells, and has Disadvantage on saves against Divination spells."],[14,"Faerzress Step","You always have Teleport prepared and can cast it once without a slot, regaining that after a Long Rest. When you roll on the Teleport table you can choose any outcome available for your familiarity."],[18,"Faerzress Form","When you use Innate Sorcery you can become pure faerzress energy for 1 minute, ending early if you choose (no action) or die. You keep your shape, personality, memories, and speech. Equipment doesn't transform, but you can still use it. You gain Immunity to Grappled, Paralyzed, Petrified, Poisoned, Prone, and Restrained. You resist every damage type except Force and Psychic. You gain a Fly Speed equal to your Speed and can hover. You can move through creatures and objects as Difficult Terrain, and take 1d10 Force damage if you end your turn inside an object. You can't use this again until a Long Rest, or until you spend 7 Sorcery Points (no action)."]],"full":{"Faerzress Sorcery|Faerzress Effects":"Faerzress is magical radiation. Within an area it fills: creatures automatically pass saves against Divination effects. Magical sensors and invisible eyes, such as from Clairvoyance or Arcane Eye, can't enter. A creature teleporting 1 mile or more can't teleport into or out of the area. The area is lit with Dim Light, and creatures using Darkvision there see in color and have Advantage on Wisdom (Perception) checks that rely on sight.","Faerzress Sorcery|Faerzress Side Effects":"Roll on or choose from the Faerzress Side Effects table to decide what odd effect the radiation you give off has on your surroundings.","Faerzress Sorcery|Faerzress Spells":"Spells always prepared from the listed Sorcerer levels: 3 Faerie Fire, Magic Weapon, Misty Step, Witch Bolt. 5 Nondetection, Sending. 7 Arcane Eye, Stone Shape. 9 Passwall, Scrying.","Faerzress Sorcery|Faerzress Zone":"Magic action, spend 3 Sorcery Points: fill an area within 120 feet, no larger than a 40-foot Cube, with faerzress for 24 hours. Filling the same area every day for 365 days makes it permanent.","Faerzress Sorcery|Immunity to Faerzress":"You ignore faerzress's harmful effects. Creatures in faerzress don't automatically pass saves against your Divination spells. Sensors and eyes from your spells can enter faerzress. When you teleport yourself or others, you can enter or leave faerzress at any distance.","Faerzress Sorcery|Faerzress Affinity":"You have Resistance to Lightning damage and Darkvision 60 feet (or +30 feet if you have it). You see color in Darkness, and have Advantage on Wisdom (Perception) checks to see in Dim Light or Darkness. Your Immunity to Faerzress also covers allies within 30 feet of you.","Faerzress Sorcery|Faerzress Spell":"When creatures fail a save against a spell you cast, you can spend 1 Sorcery Point to lace one of them with faerzress for 1 minute. It can't teleport, can't cast Divination spells, and has Disadvantage on saves against Divination spells.","Faerzress Sorcery|Faerzress Step":"You always have Teleport prepared and can cast it once without a slot, regaining that after a Long Rest. When you roll on the Teleport table you can choose any outcome available for your familiarity.","Faerzress Sorcery|Faerzress Form":"When you use Innate Sorcery you can become pure faerzress energy for 1 minute, ending early if you choose (no action) or die. You keep your shape, personality, memories, and speech. Equipment doesn't transform, but you can still use it. You gain Immunity to Grappled, Paralyzed, Petrified, Poisoned, Prone, and Restrained. You resist every damage type except Force and Psychic. You gain a Fly Speed equal to your Speed and can hover. You can move through creatures and objects as Difficult Terrain, and take 1d10 Force damage if you end your turn inside an object. You can't use this again until a Long Rest, or until you spend 7 Sorcery Points (no action)."},"auto":[[3,"Faerie Fire,Magic Weapon,Misty Step,Witch Bolt"],[5,"Nondetection,Sending"],[7,"Arcane Eye,Stone Shape"],[9,"Passwall,Scrying"]],"lu":[{"src":"sub","owner":"Faerzress Sorcery","feature":"Faerzress Step","n":"Teleport (no slot)","lvl":14,"max":1,"reset":"long","tag":"Level 7 spell"},{"src":"sub","owner":"Faerzress Sorcery","feature":"Faerzress Form","n":"Faerzress Form","lvl":18,"max":1,"reset":"long","tag":"Reset by 7 Sorcery Points"}],"acts":{"sub|Faerzress Sorcery|Faerzress Zone":[["action",""]]},"cantrips":[],"pick":[],"fx":[[6,"Faerzress Affinity",{"res":["Lightning"],"senses":[["Darkvision",60,"adds 30 ft if you have it, see color in Darkness"]]}],[18,"Faerzress Form",{"notes":[["Note","Faerzress Form (Innate Sorcery): Fly Speed equal to Speed, resist all damage but Force and Psychic, immune to several conditions, for 1 minute"]]}]],"spab":"CHA"},{"alt":[],"cls":"Cleric","name":"Freedom Domain","src":"tua24","arr":[[3,"Freedom Domain Spells","Spells always prepared from the listed Cleric levels: 3 Expeditious Retreat, Jump, Knock, Misty Step. 5 Fly, Gaseous Form. 7 Dimension Door, Freedom of Movement. 9 Passwall, Tree Stride."],[3,"Invoke Liberty","Magic action, spend a Channel Divinity use while presenting your Holy Symbol: each ally in a 30-foot Emanation can end one condition on itself from Frightened, Grappled, Paralyzed, or Restrained, then use its Reaction to move up to its Speed without Opportunity Attacks. At Cleric level 9 the list also includes Charmed and Petrified."],[3,"The Meaning of Freedom","Roll on or choose from the Foremost Freedom table to decide what freedom means most to your character."],[3,"Unencumbered Grace","While wearing no armor, your base AC is 10 + your Dexterity modifier + your Wisdom modifier. You can use a Shield and keep this. You gain proficiency in Acrobatics, or Expertise in it if you already have proficiency."],[6,"Unstoppable","Difficult Terrain doesn't affect your movement. You gain proficiency in Dexterity saving throws, or in one saving throw you lack if you already have it."],[17,"Avatar of Freedom","Bonus Action: manifest a 30-foot Emanation around you for 10 minutes, ending early if you dismiss it (no action) or are Incapacitated. When an ally first enters it on a turn or starts its turn there, its Speed rises by 30 feet until the end of its next turn. Allies in it ignore Difficult Terrain and have Advantage on Dexterity checks. You can't use this again until a Short or Long Rest."]],"full":{"Freedom Domain|Freedom Domain Spells":"Spells always prepared from the listed Cleric levels: 3 Expeditious Retreat, Jump, Knock, Misty Step. 5 Fly, Gaseous Form. 7 Dimension Door, Freedom of Movement. 9 Passwall, Tree Stride.","Freedom Domain|Invoke Liberty":"Magic action, spend a Channel Divinity use while presenting your Holy Symbol: each ally in a 30-foot Emanation can end one condition on itself from Frightened, Grappled, Paralyzed, or Restrained, then use its Reaction to move up to its Speed without Opportunity Attacks. At Cleric level 9 the list also includes Charmed and Petrified.","Freedom Domain|The Meaning of Freedom":"Roll on or choose from the Foremost Freedom table to decide what freedom means most to your character.","Freedom Domain|Unencumbered Grace":"While wearing no armor, your base AC is 10 + your Dexterity modifier + your Wisdom modifier. You can use a Shield and keep this. You gain proficiency in Acrobatics, or Expertise in it if you already have proficiency.","Freedom Domain|Unstoppable":"Difficult Terrain doesn't affect your movement. You gain proficiency in Dexterity saving throws, or in one saving throw you lack if you already have it.","Freedom Domain|Avatar of Freedom":"Bonus Action: manifest a 30-foot Emanation around you for 10 minutes, ending early if you dismiss it (no action) or are Incapacitated. When an ally first enters it on a turn or starts its turn there, its Speed rises by 30 feet until the end of its next turn. Allies in it ignore Difficult Terrain and have Advantage on Dexterity checks. You can't use this again until a Short or Long Rest."},"auto":[[3,"Expeditious Retreat,Jump,Knock,Misty Step"],[5,"Fly,Gaseous Form"],[7,"Dimension Door,Freedom of Movement"],[9,"Passwall,Tree Stride"]],"lu":[{"src":"sub","owner":"Freedom Domain","feature":"Avatar of Freedom","n":"Avatar of Freedom","lvl":17,"max":1,"reset":"short","tag":"Bonus Action"}],"acts":{"sub|Freedom Domain|Invoke Liberty":[["action",""]],"sub|Freedom Domain|Avatar of Freedom":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[3,"Unencumbered Grace",{"skills":["Acrobatics"],"notes":[["Armor","Unencumbered Grace: with no armor, base AC 10 + Dexterity modifier + Wisdom modifier (Shield allowed). Acrobatics proficiency, or Expertise if already proficient"]]}],[6,"Unstoppable",{"notes":[["Note","Unstoppable: ignore Difficult Terrain. Dexterity saving throw proficiency, or another save if you have it"]]}]],"spab":"WIS"},{"alt":[],"cls":"Rogue","name":"House Agent","src":"tua24","arr":[[3,"Charming Presence","You can take the Influence action as a Bonus Action. You also gain proficiency in one skill from Deception, Intimidation, Performance, or Persuasion."],[3,"House Insignia","You gain a magical brooch or coin that marks you as an agent of your sponsor. You cast the spells below through it, with Charisma as your spellcasting ability. You learn the Friends cantrip. You can cast Find Familiar as a Ritual only. Your sponsor supplies the Material component for the first casting, and the familiar must take the Spider form. Insignia spells: level 3 Charm Person, level 5 Suggestion, level 9 Hypnotic Pattern. After casting a spell through the insignia you can't cast it that way again until a Long Rest. If you lose the insignia, your house delivers a new one by the time you finish a Long Rest."],[3,"Loyalty Test","Roll on or choose from the House Agent Origins table to decide how you proved your loyalty to your sponsor. Your sponsor can be another large group, such as a duergar clan, a religious order, or a faction like the Zhentarim."],[9,"Backstab","You have Advantage on attack rolls against creatures within 5 feet that are Friendly to you or Charmed. You also gain the Cunning Strike option Stunning Betrayal (cost 4d6): if the target was Friendly to you or Charmed when you hit it, it is Stunned until the start of your next turn."],[13,"Infiltration Partner","Your Find Familiar familiar gains Darkvision 120 feet and Truesight 30 feet. When you cast Find Familiar, or finish a Short or Long Rest with a familiar, you can give it Temporary Hit Points equal to your Rogue level."],[13,"Silver Tongue","A creature's Hostile attitude doesn't impose Disadvantage on your Charisma checks to influence it."],[17,"Subtle Manipulator","You gain the Cunning Strike option Confound (cost 5d6): the target makes a Wisdom save against your spell save DC or is Charmed for 1 minute. It can repeat the save when it takes damage, ending the effect on a success. You can also cast Friends as a Bonus Action. The target no longer automatically succeeds on its save if it isn't a Humanoid or if you are fighting it. When a Charmed condition from a spell you cast ends, the target doesn't know you caused it."]],"full":{"House Agent|Charming Presence":"You can take the Influence action as a Bonus Action. You also gain proficiency in one skill from Deception, Intimidation, Performance, or Persuasion.","House Agent|House Insignia":"You gain a magical brooch or coin that marks you as an agent of your sponsor. You cast the spells below through it, with Charisma as your spellcasting ability. You learn the Friends cantrip. You can cast Find Familiar as a Ritual only. Your sponsor supplies the Material component for the first casting, and the familiar must take the Spider form. Insignia spells: level 3 Charm Person, level 5 Suggestion, level 9 Hypnotic Pattern. After casting a spell through the insignia you can't cast it that way again until a Long Rest. If you lose the insignia, your house delivers a new one by the time you finish a Long Rest.","House Agent|Loyalty Test":"Roll on or choose from the House Agent Origins table to decide how you proved your loyalty to your sponsor. Your sponsor can be another large group, such as a duergar clan, a religious order, or a faction like the Zhentarim.","House Agent|Backstab":"You have Advantage on attack rolls against creatures within 5 feet that are Friendly to you or Charmed. You also gain the Cunning Strike option Stunning Betrayal (cost 4d6): if the target was Friendly to you or Charmed when you hit it, it is Stunned until the start of your next turn.","House Agent|Infiltration Partner":"Your Find Familiar familiar gains Darkvision 120 feet and Truesight 30 feet. When you cast Find Familiar, or finish a Short or Long Rest with a familiar, you can give it Temporary Hit Points equal to your Rogue level.","House Agent|Silver Tongue":"A creature's Hostile attitude doesn't impose Disadvantage on your Charisma checks to influence it.","House Agent|Subtle Manipulator":"You gain the Cunning Strike option Confound (cost 5d6): the target makes a Wisdom save against your spell save DC or is Charmed for 1 minute. It can repeat the save when it takes damage, ending the effect on a success. You can also cast Friends as a Bonus Action. The target no longer automatically succeeds on its save if it isn't a Humanoid or if you are fighting it. When a Charmed condition from a spell you cast ends, the target doesn't know you caused it."},"auto":[],"lu":[{"src":"sub","owner":"House Agent","feature":"House Insignia","n":"Charm Person (insignia)","lvl":3,"max":1,"reset":"long","tag":"Level 1 spell"},{"src":"sub","owner":"House Agent","feature":"House Insignia","n":"Suggestion (insignia)","lvl":5,"max":1,"reset":"long","tag":"Level 2 spell"},{"src":"sub","owner":"House Agent","feature":"House Insignia","n":"Hypnotic Pattern (insignia)","lvl":9,"max":1,"reset":"long","tag":"Level 3 spell"}],"acts":{"sub|House Agent|Charming Presence":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[3,"Charming Presence",{"notes":[["Note","Charming Presence: Influence action as a Bonus Action. One skill from Deception, Intimidation, Performance, Persuasion"]]}],[9,"Backstab",{"notes":[["Note","Backstab: Advantage on attacks within 5 feet against Friendly or Charmed creatures"]]}],[13,"Silver Tongue",{"notes":[["Note","Silver Tongue: Hostile attitude gives no Disadvantage on your Charisma checks to influence"]]}]],"spab":"CHA"},{"alt":[],"cls":"Wizard","name":"Imaskarcanist","src":"tua24","arr":[[3,"Learning the Secrets of Unlight","Roll on or choose from the Secrets of Unlight table to decide how you learned this rare magic."],[3,"Unlight Adept","When you cast a spell that deals Acid, Cold, Fire, Lightning, or Thunder damage, you can change the damage to Radiant. Dim Light created by your spells is Bright Light instead."],[3,"Unlight Invigoration","Bonus Action: pick a willing creature you see within 30 feet and spend one or two of your Hit Point Dice. It gains Temporary Hit Points equal to the total rolled plus your Intelligence modifier. While it has any of those, it has Advantage on Strength checks and sheds Bright Light in a 10-foot radius."],[6,"Unlight Restoration","Bonus Action: pick a creature you see within 30 feet and spend one or two of your Hit Point Dice. It regains Hit Points equal to the total rolled and sheds Bright Light in a 10-foot radius until the end of its next turn. If you spent two dice, you can instead end Blinded, Deafened, Paralyzed, or Poisoned on it, and then it regains no Hit Points."],[10,"Secrets of Deep Imaskar","Imaskarcana Lore: you can attune to a magic item as a Magic action, once per Long Rest. Piercing Unlight: your spells ignore Resistance to Radiant damage. Unlight Resilience: you have Resistance to Radiant damage. Imaskar Seals: you always have Glyph of Warding prepared and can cast it once without a slot. It needs no Material components and is cast at the level of your highest Wizard spell slot. Any earlier glyph you made this way breaks and its spell ends without triggering. You regain this after a Long Rest."],[14,"Doom Of Unlight","When a creature takes Radiant damage from a spell you cast, you can use your Reaction to curse it with Unlight. It makes a Constitution save against your spell save DC. On a failure it is cursed until the curse ends. It sheds Bright Light in a 20-foot radius. Attack rolls against it have Advantage. At the start of its turns it takes Radiant damage equal to your character level. It has Advantage on Strength checks and melee attack rolls. If it hits a creature with a melee attack roll it can repeat the save to end the curse. If it drops to 0 Hit Points it explodes, and creatures in a 10-foot Emanation centered on it take Radiant damage equal to half your character level in d8. After attempting a curse you can't do so again until a Long Rest or until you spend a level 6+ spell slot (no action)."]],"full":{"Imaskarcanist|Learning the Secrets of Unlight":"Roll on or choose from the Secrets of Unlight table to decide how you learned this rare magic.","Imaskarcanist|Unlight Adept":"When you cast a spell that deals Acid, Cold, Fire, Lightning, or Thunder damage, you can change the damage to Radiant. Dim Light created by your spells is Bright Light instead.","Imaskarcanist|Unlight Invigoration":"Bonus Action: pick a willing creature you see within 30 feet and spend one or two of your Hit Point Dice. It gains Temporary Hit Points equal to the total rolled plus your Intelligence modifier. While it has any of those, it has Advantage on Strength checks and sheds Bright Light in a 10-foot radius.","Imaskarcanist|Unlight Restoration":"Bonus Action: pick a creature you see within 30 feet and spend one or two of your Hit Point Dice. It regains Hit Points equal to the total rolled and sheds Bright Light in a 10-foot radius until the end of its next turn. If you spent two dice, you can instead end Blinded, Deafened, Paralyzed, or Poisoned on it, and then it regains no Hit Points.","Imaskarcanist|Secrets of Deep Imaskar":"Imaskarcana Lore: you can attune to a magic item as a Magic action, once per Long Rest. Piercing Unlight: your spells ignore Resistance to Radiant damage. Unlight Resilience: you have Resistance to Radiant damage. Imaskar Seals: you always have Glyph of Warding prepared and can cast it once without a slot. It needs no Material components and is cast at the level of your highest Wizard spell slot. Any earlier glyph you made this way breaks and its spell ends without triggering. You regain this after a Long Rest.","Imaskarcanist|Doom Of Unlight":"When a creature takes Radiant damage from a spell you cast, you can use your Reaction to curse it with Unlight. It makes a Constitution save against your spell save DC. On a failure it is cursed until the curse ends. It sheds Bright Light in a 20-foot radius. Attack rolls against it have Advantage. At the start of its turns it takes Radiant damage equal to your character level. It has Advantage on Strength checks and melee attack rolls. If it hits a creature with a melee attack roll it can repeat the save to end the curse. If it drops to 0 Hit Points it explodes, and creatures in a 10-foot Emanation centered on it take Radiant damage equal to half your character level in d8. After attempting a curse you can't do so again until a Long Rest or until you spend a level 6+ spell slot (no action)."},"auto":[],"lu":[{"src":"sub","owner":"Imaskarcanist","feature":"Secrets of Deep Imaskar","n":"Imaskarcana Lore (attune as a Magic action)","lvl":10,"max":1,"reset":"long","tag":"Magic action"},{"src":"sub","owner":"Imaskarcanist","feature":"Secrets of Deep Imaskar","n":"Imaskar Seals (Glyph of Warding)","lvl":10,"max":1,"reset":"long","tag":"No slot, no components"},{"src":"sub","owner":"Imaskarcanist","feature":"Doom Of Unlight","n":"Doom Of Unlight","lvl":14,"max":1,"reset":"long","tag":"Reset by a level 6+ slot"}],"acts":{"sub|Imaskarcanist|Unlight Invigoration":[["bonus",""]],"sub|Imaskarcanist|Unlight Restoration":[["bonus",""]],"sub|Imaskarcanist|Doom Of Unlight":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[10,"Secrets of Deep Imaskar",{"res":["Radiant"],"notes":[["Note","Piercing Unlight: your spells ignore Resistance to Radiant damage"]]}]],"spab":"INT"},{"alt":[],"cls":"Barbarian","name":"Path of Unlight","src":"tua24","arr":[[3,"Radiant Rage","While Raging, a creature that hits you with a melee attack roll takes Radiant damage equal to your Rage Damage bonus, and you shed Bright Light in a 20-foot radius."],[3,"Unlight Manifestation","Roll on or choose from the Unlight Manifestation table to decide what form your Radiant Rage takes."],[6,"Unlight Revelation","You gain proficiency and Expertise in Perception. While Raging you have Blindsight with a range equal to the Bright Light of your Radiant Rage."],[10,"Harbinger of Unlight","You have Resistance to Radiant damage."],[10,"Infectious Unlight","Damage from your Brutal Strike can be Radiant or its usual type. You also gain the Brutal Strike option Radiant Infection: the target is infected for 1 minute, sheds Bright Light in a 10-foot radius, and takes 1d6 Radiant damage at the start of each of its turns. At the end of each of its turns it makes a Constitution save (DC 8 + Strength modifier + Proficiency Bonus), ending the effect on a success."],[14,"Brilliant Rage","While Raging you shed Bright Light in a 30-foot radius. As a Bonus Action you can unleash blinding brilliance. Each creature of your choice within 30 feet makes a Constitution save (DC 8 + Strength modifier + Proficiency Bonus). A failure takes 1d12 Radiant damage and is Blinded until the end of your next turn. A success takes half damage. After using it you can't do so again until a Long Rest, or until you spend a Rage use (no action)."]],"full":{"Path of Unlight|Radiant Rage":"While Raging, a creature that hits you with a melee attack roll takes Radiant damage equal to your Rage Damage bonus, and you shed Bright Light in a 20-foot radius.","Path of Unlight|Unlight Manifestation":"Roll on or choose from the Unlight Manifestation table to decide what form your Radiant Rage takes.","Path of Unlight|Unlight Revelation":"You gain proficiency and Expertise in Perception. While Raging you have Blindsight with a range equal to the Bright Light of your Radiant Rage.","Path of Unlight|Harbinger of Unlight":"You have Resistance to Radiant damage.","Path of Unlight|Infectious Unlight":"Damage from your Brutal Strike can be Radiant or its usual type. You also gain the Brutal Strike option Radiant Infection: the target is infected for 1 minute, sheds Bright Light in a 10-foot radius, and takes 1d6 Radiant damage at the start of each of its turns. At the end of each of its turns it makes a Constitution save (DC 8 + Strength modifier + Proficiency Bonus), ending the effect on a success.","Path of Unlight|Brilliant Rage":"While Raging you shed Bright Light in a 30-foot radius. As a Bonus Action you can unleash blinding brilliance. Each creature of your choice within 30 feet makes a Constitution save (DC 8 + Strength modifier + Proficiency Bonus). A failure takes 1d12 Radiant damage and is Blinded until the end of your next turn. A success takes half damage. After using it you can't do so again until a Long Rest, or until you spend a Rage use (no action)."},"auto":[],"lu":[{"src":"sub","owner":"Path of Unlight","feature":"Brilliant Rage","n":"Brilliant Rage","lvl":14,"max":1,"reset":"long","tag":"Reset by a Rage use"}],"acts":{"sub|Path of Unlight|Brilliant Rage":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[3,"Radiant Rage",{"notes":[["Note","Radiant Rage: while Raging, melee attackers who hit you take Radiant damage equal to your Rage Damage. Bright Light 20 feet"]]}],[6,"Unlight Revelation",{"skills":["Perception"],"exp":["Perception"]}],[10,"Harbinger of Unlight",{"res":["Radiant"]}]],"spab":""},{"alt":[],"cls":"Druid","name":"Circle of the Titan","src":"tua24","arr":[[3,"Circle of the Titan Spells","Always prepared from the listed Druid levels: 3 Enlarge/Reduce, Thunderwave, Thaumaturgy. 5 Fear. 7 Fire Shield. 9 Destructive Wave. You can also cast these spells while in your Titan Form."],[3,"Titan Form","When you use Wild Shape, you can take a Titan Form: Behemoth, Leviathan, or Insectoid. You can stay in it for 10 minutes instead of hours. Features that apply to your Beast forms also apply to it, and you choose how it looks. Titan forms (Large, Huge, or Gargantuan, your creature type does not change): AC 13 + your Wisdom modifier, Temporary Hit Points equal to 4 times your Druid level, Speed 40 ft, Darkvision 60 ft. Your Strength and Dexterity equal your Wisdom score. Siege Monster: double damage to objects and structures. Multiattack from Druid level 5: two Rend attacks. Rend: melee, your spell attack bonus, reach 10 ft, 1d8 + Wisdom modifier damage, rising to 2d8 at Druid level 6 and 3d8 at 12. Behemoth: Climb 40 ft, Slashing Rend. Incandescent Breath: spend a level 1+ slot, 5-foot-wide 60-foot Line, Dexterity save against your spell save DC, 2d10 Radiant per slot level, half on a success. Rampager (level 10): Bonus Action, spend a level 1+ slot, move up to half Speed without Opportunity Attacks. The first time you enter the space of an enemy at least two sizes smaller, it makes a Strength save or falls Prone. If already Prone it takes 1d10 Bludgeoning per slot level. Leviathan: Swim 40 ft, Amphibious, Bludgeoning Rend. Toxic Deluge (level 10): Bonus Action, spend a level 1+ slot, 10-foot Emanation, Constitution save, 2d4 Poison per slot level and Poisoned until the start of your next turn on a failure. Insectoid: Piercing Rend. Energizing Pollen: spend a level 1+ slot and move up to half Speed without Opportunity Attacks, healing each creature you pass within 5 feet for 2d6 per slot level, once per creature per turn. Level 10: Fly 40 ft and Flyby, no Opportunity Attacks when you fly out of reach."],[6,"Dire Impact","Elemental Rend: when your Titan Form's Rend hits, you can change its damage to Acid, Cold, Fire, Lightning, or Thunder. Shock Wave: once per turn, right after you move at least half your Speed, send a shock wave through a 10-foot Emanation. Each creature in it makes a Constitution save against your spell save DC or falls Prone."],[10,"Primal Havoc","Huge Size: your Titan Form can be Huge if there is room. Toughened Hide: right after you take a Huge or larger form, you can spend a level 1+ spell slot to gain an AC bonus for the form equal to half the slot's level (round up). Above It All: while Huge or larger, Difficult Terrain from heavy snow, ice, rubble, or undergrowth costs no extra movement."],[14,"Monstrous Appetite","Gargantuan Size: your Titan Form can be Gargantuan if there is room. Grappling Rend: once per turn, when you are Huge or larger and hit with Rend, you can Grapple the target (escape DC is your spell save DC), one target at a time. Swallow: Bonus Action while Gargantuan, pick a Large or smaller creature you are grappling. It makes a Strength save against your spell save DC. On a failure it is swallowed, no longer Grappled, Blinded and Restrained, has Cover from outside, and takes Acid damage at the start of each of your turns equal to a number of d12 equal to your Wisdom modifier. You can hold as many swallowed creatures as your Wisdom modifier (min 1) and must keep Concentration. If you lose Concentration or leave the form, they are expelled within 10 feet and Prone."]],"full":{"Circle of the Titan|Circle of the Titan Spells":"Always prepared from the listed Druid levels: 3 Enlarge/Reduce, Thunderwave, Thaumaturgy. 5 Fear. 7 Fire Shield. 9 Destructive Wave. You can also cast these spells while in your Titan Form.","Circle of the Titan|Titan Form":"When you use Wild Shape, you can take a Titan Form: Behemoth, Leviathan, or Insectoid. You can stay in it for 10 minutes instead of hours. Features that apply to your Beast forms also apply to it, and you choose how it looks. Titan forms (Large, Huge, or Gargantuan, your creature type does not change): AC 13 + your Wisdom modifier, Temporary Hit Points equal to 4 times your Druid level, Speed 40 ft, Darkvision 60 ft. Your Strength and Dexterity equal your Wisdom score. Siege Monster: double damage to objects and structures. Multiattack from Druid level 5: two Rend attacks. Rend: melee, your spell attack bonus, reach 10 ft, 1d8 + Wisdom modifier damage, rising to 2d8 at Druid level 6 and 3d8 at 12. Behemoth: Climb 40 ft, Slashing Rend. Incandescent Breath: spend a level 1+ slot, 5-foot-wide 60-foot Line, Dexterity save against your spell save DC, 2d10 Radiant per slot level, half on a success. Rampager (level 10): Bonus Action, spend a level 1+ slot, move up to half Speed without Opportunity Attacks. The first time you enter the space of an enemy at least two sizes smaller, it makes a Strength save or falls Prone. If already Prone it takes 1d10 Bludgeoning per slot level. Leviathan: Swim 40 ft, Amphibious, Bludgeoning Rend. Toxic Deluge (level 10): Bonus Action, spend a level 1+ slot, 10-foot Emanation, Constitution save, 2d4 Poison per slot level and Poisoned until the start of your next turn on a failure. Insectoid: Piercing Rend. Energizing Pollen: spend a level 1+ slot and move up to half Speed without Opportunity Attacks, healing each creature you pass within 5 feet for 2d6 per slot level, once per creature per turn. Level 10: Fly 40 ft and Flyby, no Opportunity Attacks when you fly out of reach.","Circle of the Titan|Dire Impact":"Elemental Rend: when your Titan Form's Rend hits, you can change its damage to Acid, Cold, Fire, Lightning, or Thunder. Shock Wave: once per turn, right after you move at least half your Speed, send a shock wave through a 10-foot Emanation. Each creature in it makes a Constitution save against your spell save DC or falls Prone.","Circle of the Titan|Primal Havoc":"Huge Size: your Titan Form can be Huge if there is room. Toughened Hide: right after you take a Huge or larger form, you can spend a level 1+ spell slot to gain an AC bonus for the form equal to half the slot's level (round up). Above It All: while Huge or larger, Difficult Terrain from heavy snow, ice, rubble, or undergrowth costs no extra movement.","Circle of the Titan|Monstrous Appetite":"Gargantuan Size: your Titan Form can be Gargantuan if there is room. Grappling Rend: once per turn, when you are Huge or larger and hit with Rend, you can Grapple the target (escape DC is your spell save DC), one target at a time. Swallow: Bonus Action while Gargantuan, pick a Large or smaller creature you are grappling. It makes a Strength save against your spell save DC. On a failure it is swallowed, no longer Grappled, Blinded and Restrained, has Cover from outside, and takes Acid damage at the start of each of your turns equal to a number of d12 equal to your Wisdom modifier. You can hold as many swallowed creatures as your Wisdom modifier (min 1) and must keep Concentration. If you lose Concentration or leave the form, they are expelled within 10 feet and Prone."},"auto":[[3,"Enlarge/reduce,Thunderwave,Thaumaturgy"],[5,"Fear"],[7,"Fire Shield"],[9,"Destructive Wave"]],"lu":[],"acts":{"sub|Circle of the Titan|Titan Form":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[3,"Titan Form",{"notes":[["Note","Titan Form: Wild Shape for 10 minutes. AC 13 + Wisdom modifier, Temporary Hit Points 4 x Druid level, Speed 40 ft, Rend with your spell attack bonus"]]}]],"spab":"WIS"},{"alt":[],"cls":"Sorcerer","name":"Demonic Sorcery","src":"tua24","arr":[[3,"Abyssal Rupture","When you use Innate Sorcery you open a rupture to the Abyss: a 10-foot-radius Sphere centered on a point you see within 30 feet. When you start Innate Sorcery, and as a Bonus Action while it is active, choose an option. At the start of each of your turns you can move the Sphere's center to a point you see within 30 feet. Demonic Lash: make a melee spell attack against a target within 5 feet of the rupture. On a hit it takes 1d8 Slashing damage, and if it is Large or smaller you can pull it up to 10 feet toward the center. Terrifying Screams: each creature in the rupture makes a Wisdom save against your spell save DC or takes 1d4 Psychic damage."],[3,"Demonic Spells","Spells always prepared from the listed Sorcerer levels: 3 Bane, Dissonant Whispers, Spike Growth, Web. 5 Dispel Magic, Bestow Curse. 7 Giant Insect, Hallucinatory Terrain. 9 Contact Other Plane, Modify Memory. 14 Summon Fiend."],[6,"Abyssal Realm","When you spend at least 1 Sorcery Point as part of a Magic action or Bonus Action on your turn, you can draw on the Abyss. You make a 10-foot Emanation from you, or fill your rupture's Sphere, with one layer's magic. Saves use your spell save DC. Gaping Maw's Frenzy: pick a horizontal direction. Creatures that fail a Charisma save must use as much movement as possible to go that way at the start of their next turn, by the safest route. Maze of Azzatar: each creature makes an Intelligence save. On a failure you are Invisible to it until the start of your next turn. Slime Pits' Haze: each creature makes a Constitution save. On a failure it is Charmed or Poisoned (your choice) until the start of your next turn."],[14,"Abyssal Conduit","Rupture Expansion: your rupture becomes a 30-foot-radius Sphere and is Difficult Terrain for your enemies. Fiendish Servant: you always have Summon Fiend prepared. You can cast it without Concentration, giving it a 1 minute duration and requiring you to pick Demon. The Fiend has Advantage on attack rolls while in your rupture."],[18,"Abyssal Explosion","Magic action: fill a 30-foot-radius Sphere with Abyssal energy. Each creature in it makes a Constitution save against your spell save DC. A failure takes 8d6 Force damage (not Fiends) and is Incapacitated until the start of your next turn. You can't use this again until a Long Rest, or until you spend 7 Sorcery Points (no action)."]],"full":{"Demonic Sorcery|Abyssal Rupture":"When you use Innate Sorcery you open a rupture to the Abyss: a 10-foot-radius Sphere centered on a point you see within 30 feet. When you start Innate Sorcery, and as a Bonus Action while it is active, choose an option. At the start of each of your turns you can move the Sphere's center to a point you see within 30 feet. Demonic Lash: make a melee spell attack against a target within 5 feet of the rupture. On a hit it takes 1d8 Slashing damage, and if it is Large or smaller you can pull it up to 10 feet toward the center. Terrifying Screams: each creature in the rupture makes a Wisdom save against your spell save DC or takes 1d4 Psychic damage.","Demonic Sorcery|Demonic Spells":"Spells always prepared from the listed Sorcerer levels: 3 Bane, Dissonant Whispers, Spike Growth, Web. 5 Dispel Magic, Bestow Curse. 7 Giant Insect, Hallucinatory Terrain. 9 Contact Other Plane, Modify Memory. 14 Summon Fiend.","Demonic Sorcery|Abyssal Realm":"When you spend at least 1 Sorcery Point as part of a Magic action or Bonus Action on your turn, you can draw on the Abyss. You make a 10-foot Emanation from you, or fill your rupture's Sphere, with one layer's magic. Saves use your spell save DC. Gaping Maw's Frenzy: pick a horizontal direction. Creatures that fail a Charisma save must use as much movement as possible to go that way at the start of their next turn, by the safest route. Maze of Azzatar: each creature makes an Intelligence save. On a failure you are Invisible to it until the start of your next turn. Slime Pits' Haze: each creature makes a Constitution save. On a failure it is Charmed or Poisoned (your choice) until the start of your next turn.","Demonic Sorcery|Abyssal Conduit":"Rupture Expansion: your rupture becomes a 30-foot-radius Sphere and is Difficult Terrain for your enemies. Fiendish Servant: you always have Summon Fiend prepared. You can cast it without Concentration, giving it a 1 minute duration and requiring you to pick Demon. The Fiend has Advantage on attack rolls while in your rupture.","Demonic Sorcery|Abyssal Explosion":"Magic action: fill a 30-foot-radius Sphere with Abyssal energy. Each creature in it makes a Constitution save against your spell save DC. A failure takes 8d6 Force damage (not Fiends) and is Incapacitated until the start of your next turn. You can't use this again until a Long Rest, or until you spend 7 Sorcery Points (no action)."},"auto":[[3,"Bane,Dissonant Whispers,Spike Growth,Web"],[5,"Dispel Magic,Bestow Curse"],[7,"Giant Insect,Hallucinatory Terrain"],[9,"Contact Other Plane,Modify Memory"],[14,"Summon Fiend"]],"lu":[{"src":"sub","owner":"Demonic Sorcery","feature":"Abyssal Explosion","n":"Abyssal Explosion","lvl":18,"max":1,"reset":"long","tag":"Reset by 7 Sorcery Points"}],"acts":{"sub|Demonic Sorcery|Abyssal Rupture":[["bonus",""]],"sub|Demonic Sorcery|Abyssal Explosion":[["action",""]]},"cantrips":[],"pick":[],"fx":[],"spab":"CHA"},{"alt":[],"cls":"Fighter","name":"Hell Knight","src":"tua24","arr":[[3,"Diabolical Gift","Devil's Sight: you see normally in Dim Light and Darkness, magical or not, within 120 feet. Devil's Talents: you know Infernal, or another language if you already do. You also gain proficiency in Deception, Performance, or Sleight of Hand (your choice)."],[3,"Hell-Forged Weapon","When you take the Attack action you can imbue each weapon you hold with hellfire. It stays so until you use this again, you are Unconscious, the weapon is 5+ feet from you for 1 minute, or you end it (no action). It sheds Dim Light in 5 feet. When you deal damage with it, you can deal Cold, Fire, or Necrotic damage instead of its normal type (chosen when you imbue it)."],[3,"Infernal Wound","You have an Infernal Wound Die, a d6. When you hit with your Hell-Forged Weapon you can deal extra damage equal to one roll of it, of the type you chose. If the target has no infernal wound, it gets one. At the start of each of its turns it takes damage of that type equal to a roll of the die. The wound lasts 1 minute, until the target regains Hit Points, or until the target or a creature within 5 feet takes an action to stanch it. You can do this a number of times equal to your Constitution modifier (min 1), regaining all uses after a Short or Long Rest."],[7,"Advanced Wounds","When you roll your Infernal Wound Die you can apply one effect. On a 6 the effect also gains its Devil's Luck. You can do this once until the start of your next turn. Purulence of Minauros: each enemy in a 5-foot Emanation from the target takes Acid damage equal to your Constitution modifier and the target is Poisoned until the end of its next turn. Devil's Luck: creatures that take the Acid damage have -1 AC until the end of your next turn. Rupture of Cania: the target takes Force damage equal to your Constitution modifier. Devil's Luck: it subtracts 1d6 from its next saving throw before the end of your next turn. Stygian Gangrene: the target takes Cold damage equal to your Constitution modifier and can't take Reactions until the start of its next turn. Devil's Luck: its Speed is halved until the end of its next turn."],[7,"Infernal Equipment","Infernal Resistance: after a Short or Long Rest choose Cold, Fire, or Necrotic. While wearing Heavy armor or wielding a Shield you resist that damage type until you choose again. Unholy Power: when you roll your Infernal Wound Die, you can treat a 1 as a 6."],[10,"Hellfire Surge","When you use Action Surge while holding a Hell-Forged Weapon, hellfire erupts in a 20-foot Emanation from you until the end of your next turn. A creature with an infernal wound that starts its turn in it takes damage equal to two rolls of your Infernal Wound Die instead of one."],[15,"Devil's Misfortune","Reaction when a creature with an infernal wound hits you with an attack roll: roll your Infernal Wound Die and reduce the damage by the roll. On a 6, roll again (up to three rolls total) and reduce the damage by the total. If the attack is a Critical Hit, it becomes a normal hit."],[18,"Infernal Bargain","When you roll a 6 on your Infernal Wound Die three or more times before the start of your next turn, you gain Heroic Inspiration. Infernal Inspiration: spend Heroic Inspiration when a creature you see within 120 feet rolls a d20 for a D20 Test, to make it reroll. If the new roll makes it succeed, you regain a use of Indomitable or Second Wind (your choice). If it makes it fail, you lose 3d6 + your Fighter level Hit Points."]],"full":{"Hell Knight|Diabolical Gift":"Devil's Sight: you see normally in Dim Light and Darkness, magical or not, within 120 feet. Devil's Talents: you know Infernal, or another language if you already do. You also gain proficiency in Deception, Performance, or Sleight of Hand (your choice).","Hell Knight|Hell-Forged Weapon":"When you take the Attack action you can imbue each weapon you hold with hellfire. It stays so until you use this again, you are Unconscious, the weapon is 5+ feet from you for 1 minute, or you end it (no action). It sheds Dim Light in 5 feet. When you deal damage with it, you can deal Cold, Fire, or Necrotic damage instead of its normal type (chosen when you imbue it).","Hell Knight|Infernal Wound":"You have an Infernal Wound Die, a d6. When you hit with your Hell-Forged Weapon you can deal extra damage equal to one roll of it, of the type you chose. If the target has no infernal wound, it gets one. At the start of each of its turns it takes damage of that type equal to a roll of the die. The wound lasts 1 minute, until the target regains Hit Points, or until the target or a creature within 5 feet takes an action to stanch it. You can do this a number of times equal to your Constitution modifier (min 1), regaining all uses after a Short or Long Rest.","Hell Knight|Advanced Wounds":"When you roll your Infernal Wound Die you can apply one effect. On a 6 the effect also gains its Devil's Luck. You can do this once until the start of your next turn. Purulence of Minauros: each enemy in a 5-foot Emanation from the target takes Acid damage equal to your Constitution modifier and the target is Poisoned until the end of its next turn. Devil's Luck: creatures that take the Acid damage have -1 AC until the end of your next turn. Rupture of Cania: the target takes Force damage equal to your Constitution modifier. Devil's Luck: it subtracts 1d6 from its next saving throw before the end of your next turn. Stygian Gangrene: the target takes Cold damage equal to your Constitution modifier and can't take Reactions until the start of its next turn. Devil's Luck: its Speed is halved until the end of its next turn.","Hell Knight|Infernal Equipment":"Infernal Resistance: after a Short or Long Rest choose Cold, Fire, or Necrotic. While wearing Heavy armor or wielding a Shield you resist that damage type until you choose again. Unholy Power: when you roll your Infernal Wound Die, you can treat a 1 as a 6.","Hell Knight|Hellfire Surge":"When you use Action Surge while holding a Hell-Forged Weapon, hellfire erupts in a 20-foot Emanation from you until the end of your next turn. A creature with an infernal wound that starts its turn in it takes damage equal to two rolls of your Infernal Wound Die instead of one.","Hell Knight|Devil's Misfortune":"Reaction when a creature with an infernal wound hits you with an attack roll: roll your Infernal Wound Die and reduce the damage by the roll. On a 6, roll again (up to three rolls total) and reduce the damage by the total. If the attack is a Critical Hit, it becomes a normal hit.","Hell Knight|Infernal Bargain":"When you roll a 6 on your Infernal Wound Die three or more times before the start of your next turn, you gain Heroic Inspiration. Infernal Inspiration: spend Heroic Inspiration when a creature you see within 120 feet rolls a d20 for a D20 Test, to make it reroll. If the new roll makes it succeed, you regain a use of Indomitable or Second Wind (your choice). If it makes it fail, you lose 3d6 + your Fighter level Hit Points."},"auto":[],"lu":[{"src":"sub","owner":"Hell Knight","feature":"Infernal Wound","n":"Infernal Wound","lvl":3,"max":"mod:CON","reset":"short","tag":"Extra damage and infernal wound"}],"acts":{"sub|Hell Knight|Devil's Misfortune":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[3,"Diabolical Gift",{"senses":[["Devil's Sight",120,""]],"notes":[["Note","Diabolical Gift: Infernal language (or another). One skill from Deception, Performance, Sleight of Hand"]]}],[7,"Infernal Equipment",{"notes":[["Note","Infernal Resistance: Resistance to Cold, Fire, or Necrotic (chosen at each rest) while in Heavy armor or holding a Shield"]]}]],"spab":""},{"alt":[],"cls":"Rogue","name":"Magic Stealer","src":"tua24","arr":[[3,"Drain Magic","Magic action: touch a willing creature and end one ongoing level 1 or 2 spell on it. The creature regains one expended spell slot of level 2 or lower (its choice). You can't use this again until a Short or Long Rest."],[3,"Empower Sneak Attack","Reaction right after a creature you see within 30 feet casts a level 1+ spell: absorb its energy. Until the end of your next turn, your next Sneak Attack hit deals extra Force damage, a number of d6 equal to the spell's level. You can do this a number of times equal to your Intelligence modifier (min 1), regaining all uses after a Long Rest."],[9,"Magical Sabotage","You gain the Cunning Strike options Disrupt Spell, Spell Susceptibility, and Steal Resistance."],[9,"Disrupt Spell (Cost: 3d6)","Cunning Strike option, cost 3d6. Until the start of your next turn, whenever the target casts a spell it makes an Intelligence save or the spell fizzles, wasting the action, Bonus Action, or Reaction used. A slot used for it is not spent."],[9,"Spell Susceptibility (Cost: 2d6)","Cunning Strike option, cost 2d6. The target has Disadvantage on its next saving throw against a spell before the start of your next turn."],[9,"Steal Resistance (Cost: 2d6)","Cunning Strike option, cost 2d6. Choose a damage type. If the target resists it, until the start of your next turn it loses that Resistance and you gain it."],[13,"Improved Drain Magic","Drain Magic becomes a Bonus Action. It can end an ongoing level 1, 2, or 3 spell, and the target regains one expended slot of level 3 or lower (its choice)."],[13,"Occult Shroud","After a Long Rest you can cast Nondetection on yourself only, with a 24-hour duration. Intelligence is your spellcasting ability for it."],[17,"Eldritch Implosion","When you use Empower Sneak Attack, you can force the target to make a Constitution save (DC 8 + Dexterity modifier + Proficiency Bonus). On a failure, the spell fizzles and the target is Stunned until the start of its next turn."]],"full":{"Magic Stealer|Drain Magic":"Magic action: touch a willing creature and end one ongoing level 1 or 2 spell on it. The creature regains one expended spell slot of level 2 or lower (its choice). You can't use this again until a Short or Long Rest.","Magic Stealer|Empower Sneak Attack":"Reaction right after a creature you see within 30 feet casts a level 1+ spell: absorb its energy. Until the end of your next turn, your next Sneak Attack hit deals extra Force damage, a number of d6 equal to the spell's level. You can do this a number of times equal to your Intelligence modifier (min 1), regaining all uses after a Long Rest.","Magic Stealer|Magical Sabotage":"You gain the Cunning Strike options Disrupt Spell, Spell Susceptibility, and Steal Resistance.","Magic Stealer|Disrupt Spell (Cost: 3d6)":"Cunning Strike option, cost 3d6. Until the start of your next turn, whenever the target casts a spell it makes an Intelligence save or the spell fizzles, wasting the action, Bonus Action, or Reaction used. A slot used for it is not spent.","Magic Stealer|Spell Susceptibility (Cost: 2d6)":"Cunning Strike option, cost 2d6. The target has Disadvantage on its next saving throw against a spell before the start of your next turn.","Magic Stealer|Steal Resistance (Cost: 2d6)":"Cunning Strike option, cost 2d6. Choose a damage type. If the target resists it, until the start of your next turn it loses that Resistance and you gain it.","Magic Stealer|Improved Drain Magic":"Drain Magic becomes a Bonus Action. It can end an ongoing level 1, 2, or 3 spell, and the target regains one expended slot of level 3 or lower (its choice).","Magic Stealer|Occult Shroud":"After a Long Rest you can cast Nondetection on yourself only, with a 24-hour duration. Intelligence is your spellcasting ability for it.","Magic Stealer|Eldritch Implosion":"When you use Empower Sneak Attack, you can force the target to make a Constitution save (DC 8 + Dexterity modifier + Proficiency Bonus). On a failure, the spell fizzles and the target is Stunned until the start of its next turn."},"auto":[],"lu":[{"src":"sub","owner":"Magic Stealer","feature":"Drain Magic","n":"Drain Magic","lvl":3,"max":1,"reset":"short","tag":"Magic action, Bonus Action at 13"},{"src":"sub","owner":"Magic Stealer","feature":"Empower Sneak Attack","n":"Empower Sneak Attack","lvl":3,"max":"mod:INT","reset":"long","tag":"Reaction"},{"src":"sub","owner":"Magic Stealer","feature":"Occult Shroud","n":"Occult Shroud","lvl":13,"max":1,"reset":"long","tag":"Nondetection on yourself, 24 hours"}],"acts":{"sub|Magic Stealer|Drain Magic":[["action",""]],"sub|Magic Stealer|Empower Sneak Attack":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[],"spab":"INT"},{"alt":[],"cls":"Paladin","name":"Oath of the Spellguard","src":"tua24","arr":[[3,"Guardian Bond","Magic action, spend a Channel Divinity use: bond with a willing creature within 5 feet for 1 hour, or until you are Unconscious. While the bonded creature is within your reach and is hit by an attack roll, you can use your Reaction to add your Charisma modifier (min +1) to its AC, which can turn the hit into a miss. You can end the bond at any time (no action), and a new bond ends the old one."],[3,"Oath of the Spellguard Spells","Spells always prepared from the listed Paladin levels: 3 Detect Magic, Shield. 5 See Invisibility, Silence. 9 Counterspell, Dispel Magic. 13 Freedom of Movement, Otiluke's Resilient Sphere. 17 Circle of Power, Hallow."],[3,"Spellguard Strike","When a creature within your reach casts a spell that has Verbal, Somatic, or Material components, you can use your Reaction to make one melee weapon attack or Unarmed Strike against it."],[7,"Aura of Concentration","You and your allies in your Aura of Protection have Advantage on Constitution saves to keep Concentration."],[15,"Spell-Breaking Blade","Right after you hit with Spellguard Strike, you can cast Counterspell as part of the same Reaction. If you cast it with a slot and it fails to stop the spell, the slot is not spent."],[20,"Eternal Spellguard","Bonus Action: empower your Aura of Protection for 1 minute or until you end it (no action). Bodyguard: the target of your Guardian Bond has Resistance to all damage while in the aura. Protection from Magic: you and allies in the aura have Advantage on saves against spells. Spell Ward: spell attack rolls against you and allies in the aura have Disadvantage. You can't use this again until a Long Rest, or until you spend a level 5 spell slot (no action)."]],"full":{"Oath of the Spellguard|Guardian Bond":"Magic action, spend a Channel Divinity use: bond with a willing creature within 5 feet for 1 hour, or until you are Unconscious. While the bonded creature is within your reach and is hit by an attack roll, you can use your Reaction to add your Charisma modifier (min +1) to its AC, which can turn the hit into a miss. You can end the bond at any time (no action), and a new bond ends the old one.","Oath of the Spellguard|Oath of the Spellguard Spells":"Spells always prepared from the listed Paladin levels: 3 Detect Magic, Shield. 5 See Invisibility, Silence. 9 Counterspell, Dispel Magic. 13 Freedom of Movement, Otiluke's Resilient Sphere. 17 Circle of Power, Hallow.","Oath of the Spellguard|Spellguard Strike":"When a creature within your reach casts a spell that has Verbal, Somatic, or Material components, you can use your Reaction to make one melee weapon attack or Unarmed Strike against it.","Oath of the Spellguard|Aura of Concentration":"You and your allies in your Aura of Protection have Advantage on Constitution saves to keep Concentration.","Oath of the Spellguard|Spell-Breaking Blade":"Right after you hit with Spellguard Strike, you can cast Counterspell as part of the same Reaction. If you cast it with a slot and it fails to stop the spell, the slot is not spent.","Oath of the Spellguard|Eternal Spellguard":"Bonus Action: empower your Aura of Protection for 1 minute or until you end it (no action). Bodyguard: the target of your Guardian Bond has Resistance to all damage while in the aura. Protection from Magic: you and allies in the aura have Advantage on saves against spells. Spell Ward: spell attack rolls against you and allies in the aura have Disadvantage. You can't use this again until a Long Rest, or until you spend a level 5 spell slot (no action)."},"auto":[[3,"Detect Magic,Shield"],[5,"See Invisibility,Silence"],[9,"Counterspell,Dispel Magic"],[13,"Freedom of Movement,Otiluke's Resilient Sphere"],[17,"Circle of Power,Hallow"]],"lu":[{"src":"sub","owner":"Oath of the Spellguard","feature":"Eternal Spellguard","n":"Eternal Spellguard","lvl":20,"max":1,"reset":"long","tag":"Reset by a level 5 slot"}],"acts":{"sub|Oath of the Spellguard|Guardian Bond":[["action",""]],"sub|Oath of the Spellguard|Spellguard Strike":[["reaction",""]],"sub|Oath of the Spellguard|Eternal Spellguard":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[7,"Aura of Concentration",{"notes":[["Note","Aura of Concentration: you and allies in your aura have Advantage on Constitution saves to keep Concentration"]]}]],"spab":"CHA"},{"alt":[],"cls":"Monk","name":"Warrior of Intoxication","src":"tua24","arr":[[3,"Bonus Proficiencies","Gain proficiency in Performance. If you already have it, pick one skill from the level 1 Monk skill list instead. You also gain proficiency with Brewer's Supplies if you lack it."],[3,"Drunken Technique","When you use Flurry of Blows, your Speed rises by 10 feet until the end of the turn, and your movement does not provoke Opportunity Attacks."],[6,"Mystic Brew","After a Short or Long Rest, while holding Brewer's Supplies, you can magically make one beverage from Cinnamon Dragon, Heavenly Spirit, or Refreshing Dip. It appears in a bottle or cask that vanishes when emptied, and any leftover beverage vanishes at your next rest. Only you gain its benefit. Drinking at least a pint takes 1 minute and gives the effect for 1 hour. When you make a beverage you can spend 1 Focus Point to extend the benefit to 8 hours."],[6,"Tipsy Sway","You gain Leap to Your Feet and Redirect Attack."],[6,"Cinnamon Dragon","Mystic Brew option. Magic action: exhale toxic flame in a 30-foot Cone. Each creature makes a Dexterity save (DC 8 + Wisdom modifier + Proficiency Bonus). A failure takes Fire damage equal to four rolls of your Martial Arts die and is Poisoned until the end of its next turn. A success takes half damage."],[6,"Heavenly Spirit","Mystic Brew option. You have Resistance to Psychic and Radiant damage."],[6,"Leap to Your Feet","Standing up from Prone costs you 5 feet of movement instead of half your Speed."],[6,"Redirect Attack","When a creature misses you with a melee attack roll, spend 1 Focus Point as a Reaction to make that attack hit another creature of your choice that you see within 5 feet of you."],[6,"Refreshing Dip","Mystic Brew option. Whenever you regain Hit Points, you regain extra Hit Points equal to a roll of your Martial Arts die."],[11,"Master Brewer","Blue Lightning and Drunkard's Luck are added to your Mystic Brew options."],[11,"Blue Lightning","Mystic Brew option. When you take a Reaction that is not an Opportunity Attack or a spell, you can make one Unarmed Strike as part of it."],[11,"Drunkard's Luck","Mystic Brew option. You gain Heroic Inspiration if you do not have it, and you can give it to yourself when you roll Initiative without it."],[17,"Intoxicated Frenzy","When you use Flurry of Blows, you can make up to three extra Unarmed Strikes with it (six total), if each strike targets a different creature this turn."]],"full":{"Warrior of Intoxication|Bonus Proficiencies":"Gain proficiency in Performance. If you already have it, pick one skill from the level 1 Monk skill list instead. You also gain proficiency with Brewer's Supplies if you lack it.","Warrior of Intoxication|Drunken Technique":"When you use Flurry of Blows, your Speed rises by 10 feet until the end of the turn, and your movement does not provoke Opportunity Attacks.","Warrior of Intoxication|Mystic Brew":"After a Short or Long Rest, while holding Brewer's Supplies, you can magically make one beverage from Cinnamon Dragon, Heavenly Spirit, or Refreshing Dip. It appears in a bottle or cask that vanishes when emptied, and any leftover beverage vanishes at your next rest. Only you gain its benefit. Drinking at least a pint takes 1 minute and gives the effect for 1 hour. When you make a beverage you can spend 1 Focus Point to extend the benefit to 8 hours.","Warrior of Intoxication|Tipsy Sway":"You gain Leap to Your Feet and Redirect Attack.","Warrior of Intoxication|Cinnamon Dragon":"Mystic Brew option. Magic action: exhale toxic flame in a 30-foot Cone. Each creature makes a Dexterity save (DC 8 + Wisdom modifier + Proficiency Bonus). A failure takes Fire damage equal to four rolls of your Martial Arts die and is Poisoned until the end of its next turn. A success takes half damage.","Warrior of Intoxication|Heavenly Spirit":"Mystic Brew option. You have Resistance to Psychic and Radiant damage.","Warrior of Intoxication|Leap to Your Feet":"Standing up from Prone costs you 5 feet of movement instead of half your Speed.","Warrior of Intoxication|Redirect Attack":"When a creature misses you with a melee attack roll, spend 1 Focus Point as a Reaction to make that attack hit another creature of your choice that you see within 5 feet of you.","Warrior of Intoxication|Refreshing Dip":"Mystic Brew option. Whenever you regain Hit Points, you regain extra Hit Points equal to a roll of your Martial Arts die.","Warrior of Intoxication|Master Brewer":"Blue Lightning and Drunkard's Luck are added to your Mystic Brew options.","Warrior of Intoxication|Blue Lightning":"Mystic Brew option. When you take a Reaction that is not an Opportunity Attack or a spell, you can make one Unarmed Strike as part of it.","Warrior of Intoxication|Drunkard's Luck":"Mystic Brew option. You gain Heroic Inspiration if you do not have it, and you can give it to yourself when you roll Initiative without it.","Warrior of Intoxication|Intoxicated Frenzy":"When you use Flurry of Blows, you can make up to three extra Unarmed Strikes with it (six total), if each strike targets a different creature this turn."},"auto":[],"lu":[],"acts":{"sub|Warrior of Intoxication|Cinnamon Dragon":[["action",""]],"sub|Warrior of Intoxication|Redirect Attack":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[3,"Bonus Proficiencies",{"skills":["Performance"],"notes":[["Note","Bonus Proficiencies: Performance, or another Monk skill if you have it. Brewer's Supplies"]]}],[3,"Drunken Technique",{"notes":[["Note","Drunken Technique: Flurry of Blows gives +10 feet Speed and no Opportunity Attacks that turn"]]}],[6,"Heavenly Spirit",{"res":["Psychic","Radiant"],"notes":[["Note","Heavenly Spirit: needs the Mystic Brew of the same name"]]}],[6,"Redirect Attack",{"notes":[["Note","Redirect Attack (Reaction, 1 Focus Point): turn a melee miss into a hit on another creature within 5 feet"]]}]],"spab":"WIS"},{"alt":[],"cls":"Fighter","name":"Purple Dragon Knight","src":"tua24","arr":[[3,"Knightly Envoy","Learn one language of your choice from the Player's Handbook tables. You can cast Comprehend Languages as a Ritual only. Intelligence is your spellcasting ability for it."],[3,"Purple Dragon Companion","You are psionically bonded to an amethyst dragon hatchling that uses the Purple Dragon Companion stat block. It is Friendly to you and your allies and obeys you. In combat it acts on your turn. It moves and uses its Reaction on its own, but takes only the Dodge action unless you use a Bonus Action to command another action. If you are Incapacitated it acts on its own. If it died within the last hour, you can touch it as a Magic action and spend a Second Wind use. It returns after 1 minute with full Hit Points. Otherwise a 1-hour ceremony, which can be part of a rest, brings it back. Stat block: Small dragon, AC 13 + your Intelligence modifier, Hit Points 4 + 4 times your Fighter level (Hit Dice d6 equal to your Fighter level), Speed 30 ft, Fly 30 ft, Swim 30 ft. Str 16, Dex 16, Con 12, Int 8, Wis 13, Cha 10. Darkvision 60 ft. It understands your languages and has telepathy 30 ft. Amphibious: breathes air and water. Stalwart Bond: add half your Proficiency Bonus (round down) to its ability checks and saves. Rend: melee, +3 + your Intelligence modifier to hit, reach 5 ft, 1d6 + your Intelligence modifier Force. Gravity Breath (2/Day): 15-foot Cone, Constitution save (DC 8 + your Proficiency Bonus + your Intelligence modifier). On a failure it is pulled 15 feet toward the dragon or pushed 15 feet away (your choice)."],[7,"Dragon Rider","Dragon Mount: the dragon becomes Medium. You can ride it if you are Medium or smaller, but while you ride it, it falls at the end of its turn if the only thing keeping it up is its Fly Speed. Mounting or dismounting costs 5 feet of movement. Improved Gravity Breath: it becomes a 30-foot Cone, and a creature that fails the save also takes 2d6 Force damage. Shared Second Wind: when you use Second Wind, the dragon regains 1d6 + your Fighter level Hit Points and one use of Gravity Breath."],[10,"Advance","Rallying Surge option. The ally makes one weapon attack or Unarmed Strike. If your purple dragon uses Advance, it can make one Rend attack."],[10,"Retreat","Rallying Surge option. The ally moves up to half its Speed without provoking Opportunity Attacks."],[10,"Rallying Surge","When you use Action Surge, choose up to three allies in a 30-foot Emanation from you. Each can use its Reaction for Advance or Retreat."],[15,"Superior Mount","The dragon becomes Large and its Speed and Fly Speed rise to 40 feet. It no longer falls at the end of its turn while you ride it."],[15,"Tandem Attack","When you take the Attack action, you can give up one attack to command the dragon to make one Rend attack, or give up two attacks to command it to use Gravity Breath."],[15,"Amethyst Pinnacle","You and your purple dragon gain Superior Mount and Tandem Attack."],[18,"Enduring Commander","You and your purple dragon have Resistance to Force and Psychic damage."]],"full":{"Purple Dragon Knight|Knightly Envoy":"Learn one language of your choice from the Player's Handbook tables. You can cast Comprehend Languages as a Ritual only. Intelligence is your spellcasting ability for it.","Purple Dragon Knight|Purple Dragon Companion":"You are psionically bonded to an amethyst dragon hatchling that uses the Purple Dragon Companion stat block. It is Friendly to you and your allies and obeys you. In combat it acts on your turn. It moves and uses its Reaction on its own, but takes only the Dodge action unless you use a Bonus Action to command another action. If you are Incapacitated it acts on its own. If it died within the last hour, you can touch it as a Magic action and spend a Second Wind use. It returns after 1 minute with full Hit Points. Otherwise a 1-hour ceremony, which can be part of a rest, brings it back. Stat block: Small dragon, AC 13 + your Intelligence modifier, Hit Points 4 + 4 times your Fighter level (Hit Dice d6 equal to your Fighter level), Speed 30 ft, Fly 30 ft, Swim 30 ft. Str 16, Dex 16, Con 12, Int 8, Wis 13, Cha 10. Darkvision 60 ft. It understands your languages and has telepathy 30 ft. Amphibious: breathes air and water. Stalwart Bond: add half your Proficiency Bonus (round down) to its ability checks and saves. Rend: melee, +3 + your Intelligence modifier to hit, reach 5 ft, 1d6 + your Intelligence modifier Force. Gravity Breath (2/Day): 15-foot Cone, Constitution save (DC 8 + your Proficiency Bonus + your Intelligence modifier). On a failure it is pulled 15 feet toward the dragon or pushed 15 feet away (your choice).","Purple Dragon Knight|Dragon Rider":"Dragon Mount: the dragon becomes Medium. You can ride it if you are Medium or smaller, but while you ride it, it falls at the end of its turn if the only thing keeping it up is its Fly Speed. Mounting or dismounting costs 5 feet of movement. Improved Gravity Breath: it becomes a 30-foot Cone, and a creature that fails the save also takes 2d6 Force damage. Shared Second Wind: when you use Second Wind, the dragon regains 1d6 + your Fighter level Hit Points and one use of Gravity Breath.","Purple Dragon Knight|Advance":"Rallying Surge option. The ally makes one weapon attack or Unarmed Strike. If your purple dragon uses Advance, it can make one Rend attack.","Purple Dragon Knight|Retreat":"Rallying Surge option. The ally moves up to half its Speed without provoking Opportunity Attacks.","Purple Dragon Knight|Rallying Surge":"When you use Action Surge, choose up to three allies in a 30-foot Emanation from you. Each can use its Reaction for Advance or Retreat.","Purple Dragon Knight|Superior Mount":"The dragon becomes Large and its Speed and Fly Speed rise to 40 feet. It no longer falls at the end of its turn while you ride it.","Purple Dragon Knight|Tandem Attack":"When you take the Attack action, you can give up one attack to command the dragon to make one Rend attack, or give up two attacks to command it to use Gravity Breath.","Purple Dragon Knight|Amethyst Pinnacle":"You and your purple dragon gain Superior Mount and Tandem Attack.","Purple Dragon Knight|Enduring Commander":"You and your purple dragon have Resistance to Force and Psychic damage."},"auto":[],"lu":[{"src":"sub","owner":"Purple Dragon Knight","feature":"Purple Dragon Companion","n":"Gravity Breath (dragon)","lvl":3,"max":2,"reset":"long","tag":"Dragon action"}],"acts":{"sub|Purple Dragon Knight|Purple Dragon Companion":[["bonus",""]]},"cantrips":[],"pick":[],"fx":[[18,"Enduring Commander",{"res":["Force","Psychic"]}]],"spab":"INT"},{"alt":[],"cls":"Monk","name":"Tattooed Warrior","src":"tua24","arr":[[3,"Beast Tattoos","You gain two animal tattoos of your choice: Bat, Butterfly, Crane, Horse, or Tortoise."],[3,"Magic Tattoos","The tattoos from this subclass appear wherever you like, and injury doesn't impair them. A tattoo's save DC is 8 + your Wisdom modifier + your Proficiency Bonus. Wisdom is your spellcasting ability for spells a tattoo grants. After a Long Rest you can swap one of your tattoos for another from the same list."],[6,"Celestial Tattoo","You gain one celestial tattoo of your choice: Comet, Eclipse, or Sunburst."],[11,"Nature Tattoo","You gain one nature tattoo of your choice: Sea Storm or Volcano."],[17,"Monster Tattoo","You gain one monster tattoo of your choice: Beholder, Chromatic Dragon, Displacer Beast, or Troll."]],"full":{"Tattooed Warrior|Beast Tattoos":"You gain two animal tattoos of your choice: Bat, Butterfly, Crane, Horse, or Tortoise.","Tattooed Warrior|Magic Tattoos":"The tattoos from this subclass appear wherever you like, and injury doesn't impair them. A tattoo's save DC is 8 + your Wisdom modifier + your Proficiency Bonus. Wisdom is your spellcasting ability for spells a tattoo grants. After a Long Rest you can swap one of your tattoos for another from the same list.","Tattooed Warrior|Celestial Tattoo":"You gain one celestial tattoo of your choice: Comet, Eclipse, or Sunburst.","Tattooed Warrior|Nature Tattoo":"You gain one nature tattoo of your choice: Sea Storm or Volcano.","Tattooed Warrior|Monster Tattoo":"You gain one monster tattoo of your choice: Beholder, Chromatic Dragon, Displacer Beast, or Troll."},"auto":[],"lu":[],"acts":{},"cantrips":[],"pick":[{"l":3,"k":"opts","n":2,"key":"tat_beast","feature":"Beast Tattoos","title":"Beast tattoos (two)","list":[["Bat","You know the Dancing Lights cantrip and have Blindsight 10 feet."],["Butterfly","You know the Light cantrip. For a High Jump you can use your Dexterity modifier instead of Strength."],["Crane","You know the Guidance cantrip. When an attack from Flurry of Blows misses a creature, you have Advantage on your next attack roll against it before the end of your next turn."],["Horse","You know the Message cantrip. When you spend 1 Focus Point on Step of the Wind, your Speed rises by 10 feet until the start of your next turn."],["Tortoise","You know the Spare the Dying cantrip. When you spend 1 Focus Point on Patient Defense, you have +1 AC until the start of your next turn."]]},{"l":6,"k":"opts","n":1,"key":"tat_celestial","feature":"Celestial Tattoo","title":"Celestial tattoo","list":[["Comet","When you take the Search action, spend 1 Focus Point to add a roll of your Martial Arts die to the Wisdom check."],["Eclipse","When you take the Hide action, spend 1 Focus Point to add a roll of your Martial Arts die to the Dexterity (Stealth) check."],["Sunburst","When you take the Study action, spend 1 Focus Point to add a roll of your Martial Arts die to the Intelligence check."]]},{"l":11,"k":"opts","n":1,"key":"tat_nature","feature":"Nature Tattoo","title":"Nature tattoo","list":[["Sea Storm","You have Resistance to Cold, Lightning, or Thunder damage (your choice). You can change the choice after a Short or Long Rest or when you use Uncanny Metabolism."],["Volcano","You have Resistance to Acid, Fire, or Poison damage (your choice). You can change the choice after a Short or Long Rest or when you use Uncanny Metabolism."]]},{"l":17,"k":"opts","n":1,"key":"tat_monster","feature":"Monster Tattoo","title":"Monster tattoo","list":[["Beholder","At the start of your turn, spend 1 Focus Point to gain a Fly Speed equal to your Speed for 10 minutes, and you can hover. Magic action, spend 1 Focus Point: fire four rays from your eyes at one target within 120 feet or several. Make a ranged spell attack for each ray with Wisdom as your spellcasting ability. A hit deals Force damage equal to one roll of your Martial Arts die + your Wisdom modifier."],["Chromatic Dragon","When you take the Attack action, spend 1 Focus Point to replace one attack with a 30-foot Cone of magical energy. Choose Acid, Cold, Fire, Lightning, or Poison. Each creature makes a Dexterity save. A failure takes two rolls of your Martial Arts die + your Wisdom modifier damage of that type, a success takes half."],["Displacer Beast","When you spend a Focus Point on Flurry of Blows or Step of the Wind, you can spend 1 more Focus Point to cast Mirror Image as part of that Bonus Action."],["Troll","At the start of each of your turns, if you are Bloodied and have at least 1 Hit Point, you regain 5 + your Wisdom modifier Hit Points. A severed body part regrows after a Short or Long Rest."]]}],"fx":[],"spab":"WIS"},{"alt":[],"cls":"Sorcerer","name":"Ancestral Sorcery","src":"tua24","arr":[[3,"Ancestor's Lore","Add your Charisma modifier (min +1) to your Intelligence checks. You also gain proficiency in one skill from Arcana, History, Investigation, Nature, or Religion."],[3,"Ancestral Spells","Spells always prepared from the listed Sorcerer levels: 3 Command, Guidance, Locate Object, Protection from Evil and Good, Resistance, Spiritual Weapon. 5 Magic Circle, Spirit Guardians. 7 Divination, Locate Creature. 9 Legend Lore, Yolande's Regal Presence."],[3,"Visage of the Ancestor","Pick the form your ancestor takes. While Innate Sorcery is active, that form shows as a spectral haze around you, and you have Advantage on ability checks you make as part of the Influence action."],[6,"Superior Spell Disruption","You always have Counterspell and Dispel Magic prepared. While Innate Sorcery is active, you can cast each without a spell slot. A Counterspell cast this way gives the target Disadvantage on its Constitution save. A Dispel Magic cast this way gives you Advantage on the ability check to end a spell. After casting either one without a slot you can't do so again until a Long Rest."],[14,"Ancestral Majesty","While Innate Sorcery is active, a 5-foot Emanation of awe or dread surrounds you. When a creature you see enters it or ends its turn there, you can force a Charisma save. On a failure it is Prone or Frightened until the end of your next turn (your choice). A creature makes this save once per turn."],[14,"Steady Spellcaster","Taking damage can't break your Concentration on Sorcerer spells."],[18,"Ancestor's Ward","While Innate Sorcery is active you have Advantage on saving throws against spells. Once during each use of Innate Sorcery, when you fail a save against a spell, you can succeed instead."]],"full":{"Ancestral Sorcery|Ancestor's Lore":"Add your Charisma modifier (min +1) to your Intelligence checks. You also gain proficiency in one skill from Arcana, History, Investigation, Nature, or Religion.","Ancestral Sorcery|Ancestral Spells":"Spells always prepared from the listed Sorcerer levels: 3 Command, Guidance, Locate Object, Protection from Evil and Good, Resistance, Spiritual Weapon. 5 Magic Circle, Spirit Guardians. 7 Divination, Locate Creature. 9 Legend Lore, Yolande's Regal Presence.","Ancestral Sorcery|Visage of the Ancestor":"Pick the form your ancestor takes. While Innate Sorcery is active, that form shows as a spectral haze around you, and you have Advantage on ability checks you make as part of the Influence action.","Ancestral Sorcery|Superior Spell Disruption":"You always have Counterspell and Dispel Magic prepared. While Innate Sorcery is active, you can cast each without a spell slot. A Counterspell cast this way gives the target Disadvantage on its Constitution save. A Dispel Magic cast this way gives you Advantage on the ability check to end a spell. After casting either one without a slot you can't do so again until a Long Rest.","Ancestral Sorcery|Ancestral Majesty":"While Innate Sorcery is active, a 5-foot Emanation of awe or dread surrounds you. When a creature you see enters it or ends its turn there, you can force a Charisma save. On a failure it is Prone or Frightened until the end of your next turn (your choice). A creature makes this save once per turn.","Ancestral Sorcery|Steady Spellcaster":"Taking damage can't break your Concentration on Sorcerer spells.","Ancestral Sorcery|Ancestor's Ward":"While Innate Sorcery is active you have Advantage on saving throws against spells. Once during each use of Innate Sorcery, when you fail a save against a spell, you can succeed instead."},"auto":[[3,"Command,Guidance,Locate Object,Protection From Evil and Good,Resistance,Spiritual Weapon"],[5,"Magic Circle,Spirit Guardians"],[7,"Divination,Locate Creature"],[9,"Legend Lore,Yolande's Regal Presence"]],"lu":[{"src":"sub","owner":"Ancestral Sorcery","feature":"Superior Spell Disruption","n":"Free Counterspell or Dispel Magic","lvl":6,"max":2,"reset":"long","tag":"One per spell"},{"src":"sub","owner":"Ancestral Sorcery","feature":"Ancestor's Ward","n":"Ancestor's Ward","lvl":18,"max":1,"reset":"long","tag":"Per Innate Sorcery"}],"acts":{},"cantrips":[],"pick":[],"fx":[[3,"Ancestor's Lore",{"notes":[["Note","Ancestor's Lore: add Charisma modifier (min +1) to Intelligence checks. One skill from Arcana, History, Investigation, Nature, Religion"]]}],[14,"Steady Spellcaster",{"notes":[["Note","Steady Spellcaster: damage can't break Concentration on Sorcerer spells"]]}],[18,"Ancestor's Ward",{"advOn":["saving throws against spells while Innate Sorcery is active"]}]],"spab":"CHA"},{"alt":[],"cls":"Warlock","name":"Hexblade Patron","src":"tua24","arr":[[3,"Hexblade Spells","Spells always prepared from the listed Warlock levels: 3 Arcane Vigor, Hex, Shield, Wrathful Smite. 5 Bestow Curse, Conjure Barrage. 7 Freedom of Movement, Staggering Smite. 9 Animate Objects, Steel Wind Strike."],[3,"Hexblade's Curse","Bonus Action: curse a creature you see within 30 feet for 1 minute. It ends early if you use this again, dismiss it (no action), or die. You can use it a number of times equal to your Charisma modifier (min 1), regaining all uses after a Long Rest. When you cast a spell with a slot that curses a target, you can apply this curse to that target as part of the cast, and its duration is 1 minute or the spell's duration, whichever is longer. Hungering Hex: when the cursed target drops to 0 Hit Points you regain 1d8 + your Charisma modifier Hit Points. Accursed Shield: wearing no armor and holding no Shield, you get +2 AC while within 10 feet of the cursed target."],[3,"Unyielding Will","When you succeed on a Concentration save, each creature of your choice in a 10-foot Emanation takes 2d6 Necrotic damage. You can do this once until the start of your next turn. When you fail a Concentration save you can succeed instead and gain Temporary Hit Points equal to 1d10 + your Warlock level. You can do that once per Long Rest."],[6,"Malign Brutality","Harrowing Hex: after you cast a level 1+ spell with an action casting time, make one weapon attack as a Bonus Action. Hindering Curse: when you hit the cursed target with an attack roll, it has Disadvantage on the next saving throw it makes before the start of your next turn. Inescapable Hex: when the cursed target ends its turn 30 feet or more from you, you can move up to your Speed straight toward it."],[10,"Armor of Hexes","Reaction when you take damage from the cursed target: reduce the damage by your Warlock level."],[14,"Masterful Hex","Accursed Critical: your attack rolls against the cursed target score a Critical Hit on a 19 or 20. Explosive Hex: when you damage the cursed target, you can make the curse explode. The target and each creature of your choice in a 30-foot Emanation from it take 3d6 Necrotic, Psychic, or Radiant damage (your choice), and their Speed drops by 10 feet until the start of your next turn. After using it you can't do so again until a Long Rest, or until you spend a Pact Magic slot (no action). Hex Restoration: you regain one use of Hexblade's Curse after a Short Rest or when you use Magical Cunning."]],"full":{"Hexblade Patron|Hexblade Spells":"Spells always prepared from the listed Warlock levels: 3 Arcane Vigor, Hex, Shield, Wrathful Smite. 5 Bestow Curse, Conjure Barrage. 7 Freedom of Movement, Staggering Smite. 9 Animate Objects, Steel Wind Strike.","Hexblade Patron|Hexblade's Curse":"Bonus Action: curse a creature you see within 30 feet for 1 minute. It ends early if you use this again, dismiss it (no action), or die. You can use it a number of times equal to your Charisma modifier (min 1), regaining all uses after a Long Rest. When you cast a spell with a slot that curses a target, you can apply this curse to that target as part of the cast, and its duration is 1 minute or the spell's duration, whichever is longer. Hungering Hex: when the cursed target drops to 0 Hit Points you regain 1d8 + your Charisma modifier Hit Points. Accursed Shield: wearing no armor and holding no Shield, you get +2 AC while within 10 feet of the cursed target.","Hexblade Patron|Unyielding Will":"When you succeed on a Concentration save, each creature of your choice in a 10-foot Emanation takes 2d6 Necrotic damage. You can do this once until the start of your next turn. When you fail a Concentration save you can succeed instead and gain Temporary Hit Points equal to 1d10 + your Warlock level. You can do that once per Long Rest.","Hexblade Patron|Malign Brutality":"Harrowing Hex: after you cast a level 1+ spell with an action casting time, make one weapon attack as a Bonus Action. Hindering Curse: when you hit the cursed target with an attack roll, it has Disadvantage on the next saving throw it makes before the start of your next turn. Inescapable Hex: when the cursed target ends its turn 30 feet or more from you, you can move up to your Speed straight toward it.","Hexblade Patron|Armor of Hexes":"Reaction when you take damage from the cursed target: reduce the damage by your Warlock level.","Hexblade Patron|Masterful Hex":"Accursed Critical: your attack rolls against the cursed target score a Critical Hit on a 19 or 20. Explosive Hex: when you damage the cursed target, you can make the curse explode. The target and each creature of your choice in a 30-foot Emanation from it take 3d6 Necrotic, Psychic, or Radiant damage (your choice), and their Speed drops by 10 feet until the start of your next turn. After using it you can't do so again until a Long Rest, or until you spend a Pact Magic slot (no action). Hex Restoration: you regain one use of Hexblade's Curse after a Short Rest or when you use Magical Cunning."},"auto":[[3,"Arcane Vigor,Hex,Shield,Wrathful Smite"],[5,"Bestow Curse,Conjure Barrage"],[7,"Freedom of Movement,Staggering Smite"],[9,"Animate Objects,Steel Wind Strike"]],"lu":[{"src":"sub","owner":"Hexblade Patron","feature":"Hexblade's Curse","n":"Hexblade's Curse","lvl":3,"max":"mod:CHA","reset":"long","tag":"Bonus Action"},{"src":"sub","owner":"Hexblade Patron","feature":"Unyielding Will","n":"Unyielding Will (fail to succeed)","lvl":3,"max":1,"reset":"long","tag":"On a failed Concentration save"},{"src":"sub","owner":"Hexblade Patron","feature":"Masterful Hex","n":"Explosive Hex","lvl":14,"max":1,"reset":"long","tag":"Reset by a Pact Magic slot"}],"acts":{"sub|Hexblade Patron|Hexblade's Curse":[["bonus",""]],"sub|Hexblade Patron|Armor of Hexes":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[3,"Hexblade's Curse",{"notes":[["Note","Hexblade's Curse: +2 AC (no armor or Shield) within 10 feet of the cursed target. Heal 1d8 + Charisma modifier when it drops to 0 HP"]]}],[14,"Masterful Hex",{"notes":[["Note","Accursed Critical: 19-20 is a Critical Hit against the cursed target"]]}]],"spab":"CHA"},{"alt":[],"cls":"Druid","name":"Circle of Preservation","src":"tua24","arr":[[3,"Circle of Preservation Spells","Spells always prepared from the listed Druid levels: 3 Bless, Lesser Restoration, Protection from Poison, Sanctuary. 5 Beacon of Hope, Plant Growth. 7 Aura of Life, Death Ward. 9 Greater Restoration, Hallow."],[3,"Preserved Land","Bonus Action, spend a Wild Shape use: a 15-foot Cube of restoring energy appears on the ground within 120 feet. It lasts 1 minute and ends if you are Incapacitated, die, or move more than 120 feet from it. When a creature, you included, ends its turn in the Cube, you give it one benefit. Bolster: Temporary Hit Points equal to 1d4 + your Druid level. Purify: end one effect on it that causes Frightened or Poisoned. Plants native to the area also sprout in the Cube until it ends. On later turns you can move the Cube up to 30 feet with a Bonus Action."],[3,"Student of Preservation","When you cast a Druid spell you can skip its Material components, unless they have a listed cost or the spell consumes them. When a spell consumes a Material component, there is a 10 percent chance it is not consumed. You also gain proficiency with one Artisan's Tools of your choice."],[6,"Improved Preservation","Fortify Protectors: while in the Cube you and your allies add your Wisdom modifier (min +1) to Constitution saving throws. Reject Desecrators: when the Cube moves into an enemy's space, or an enemy enters it or ends its turn there, that enemy makes a Wisdom save against your spell save DC (once per turn per enemy). Failure: 2d10 Radiant damage and its Speed is halved until the end of its next turn. Success: half damage only."],[10,"Facilitated Restoration","Cast Lesser Restoration or Greater Restoration without a spell slot or components. You can do this a number of times equal to your Wisdom modifier (min 1), and regain all uses after a Long Rest."],[14,"Sacrosanct Land","Preserved Land becomes a 30-foot Cube. When a creature you can see in it is hit by an attack roll, you can use your Reaction to halve that attack's damage to it."]],"full":{"Circle of Preservation|Circle of Preservation Spells":"Spells always prepared from the listed Druid levels: 3 Bless, Lesser Restoration, Protection from Poison, Sanctuary. 5 Beacon of Hope, Plant Growth. 7 Aura of Life, Death Ward. 9 Greater Restoration, Hallow.","Circle of Preservation|Preserved Land":"Bonus Action, spend a Wild Shape use: a 15-foot Cube of restoring energy appears on the ground within 120 feet. It lasts 1 minute and ends if you are Incapacitated, die, or move more than 120 feet from it. When a creature, you included, ends its turn in the Cube, you give it one benefit. Bolster: Temporary Hit Points equal to 1d4 + your Druid level. Purify: end one effect on it that causes Frightened or Poisoned. Plants native to the area also sprout in the Cube until it ends. On later turns you can move the Cube up to 30 feet with a Bonus Action.","Circle of Preservation|Student of Preservation":"When you cast a Druid spell you can skip its Material components, unless they have a listed cost or the spell consumes them. When a spell consumes a Material component, there is a 10 percent chance it is not consumed. You also gain proficiency with one Artisan's Tools of your choice.","Circle of Preservation|Improved Preservation":"Fortify Protectors: while in the Cube you and your allies add your Wisdom modifier (min +1) to Constitution saving throws. Reject Desecrators: when the Cube moves into an enemy's space, or an enemy enters it or ends its turn there, that enemy makes a Wisdom save against your spell save DC (once per turn per enemy). Failure: 2d10 Radiant damage and its Speed is halved until the end of its next turn. Success: half damage only.","Circle of Preservation|Facilitated Restoration":"Cast Lesser Restoration or Greater Restoration without a spell slot or components. You can do this a number of times equal to your Wisdom modifier (min 1), and regain all uses after a Long Rest.","Circle of Preservation|Sacrosanct Land":"Preserved Land becomes a 30-foot Cube. When a creature you can see in it is hit by an attack roll, you can use your Reaction to halve that attack's damage to it."},"auto":[[3,"Bless,Lesser Restoration,Protection From Poison,Sanctuary"],[5,"Beacon of Hope,Plant Growth"],[7,"Aura of Life,Death Ward"],[9,"Greater Restoration,Hallow"]],"lu":[{"src":"sub","owner":"Circle of Preservation","feature":"Facilitated Restoration","n":"Facilitated Restoration","lvl":10,"max":"mod:WIS","reset":"long","tag":"Lesser or Greater Restoration"}],"acts":{"sub|Circle of Preservation|Preserved Land":[["bonus",""]],"sub|Circle of Preservation|Sacrosanct Land":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[3,"Student of Preservation",{"notes":[["Note","Student of Preservation: one Artisan's Tools proficiency of your choice. Druid spells need no Material components unless costed or consumed"]]}],[6,"Improved Preservation",{"notes":[["Note","Improved Preservation: in your Preserved Land, +Wisdom modifier (min +1) to Constitution saves for you and allies"]]}]],"spab":"WIS"},{"alt":[],"cls":"Sorcerer","name":"Defiled Sorcery","src":"tua24","arr":[[3,"Defile and Empower","Once per turn, when you roll damage for a spell cast with a spell slot, you can feed it your life force. Roll up to half the slot's level (round up, min 1) of your unspent Hit Point Dice and add the total to one damage roll. Those dice are spent. Life Steal: instead, pick a creature you see within 30 feet. It makes a Constitution save against your spell save DC (creatures immune to Exhaustion pass automatically). On a failure, roll its unspent Hit Point Dice instead (up to half the slot's level, round down, min 1), add the total to the damage, and the dice are spent for it. After a creature fails against Life Steal you can't use it again until a Long Rest, or until you spend 3 Sorcery Points (no action)."],[3,"Defiler Spells","Spells always prepared from the listed Sorcerer levels: 3 Blindness/Deafness, Inflict Wounds, Ray of Enfeeblement, Ray of Sickness. 5 Bestow Curse, Vampiric Touch. 7 Blight, Hallucinatory Terrain. 9 Antilife Shell, Contagion."],[6,"Corrupted Caster","Defiler's Ward: when you turn Sorcery Points into a spell slot (Bonus Action), you can roll a d6 per level of the new slot and gain that many Temporary Hit Points. While you have them, a creature that hits you with a melee attack takes Necrotic or Poison damage (your choice) equal to your Charisma modifier. Strengthened Rot: your Sorcerer spells and features ignore Resistance to Necrotic and Poison damage."],[14,"Withering Aura","When you use Innate Sorcery, a 15-foot Emanation of defiling magic surrounds you while it lasts. Defiling Shroud: when an enemy in the aura hits you with an attack roll, reduce the damage by your Charisma modifier. Essence Siphon: when an enemy in the aura dies, you regain 1d4 Sorcery Points. You can do this once per use of Innate Sorcery."],[18,"Superior Defiler","Fouled Soul: you have Immunity to the Poisoned and Exhaustion conditions. Furthered Defilement: Withering Aura grows to a 30-foot Emanation, and enemies in it can't regain Hit Points."]],"full":{"Defiled Sorcery|Defile and Empower":"Once per turn, when you roll damage for a spell cast with a spell slot, you can feed it your life force. Roll up to half the slot's level (round up, min 1) of your unspent Hit Point Dice and add the total to one damage roll. Those dice are spent. Life Steal: instead, pick a creature you see within 30 feet. It makes a Constitution save against your spell save DC (creatures immune to Exhaustion pass automatically). On a failure, roll its unspent Hit Point Dice instead (up to half the slot's level, round down, min 1), add the total to the damage, and the dice are spent for it. After a creature fails against Life Steal you can't use it again until a Long Rest, or until you spend 3 Sorcery Points (no action).","Defiled Sorcery|Defiler Spells":"Spells always prepared from the listed Sorcerer levels: 3 Blindness/Deafness, Inflict Wounds, Ray of Enfeeblement, Ray of Sickness. 5 Bestow Curse, Vampiric Touch. 7 Blight, Hallucinatory Terrain. 9 Antilife Shell, Contagion.","Defiled Sorcery|Corrupted Caster":"Defiler's Ward: when you turn Sorcery Points into a spell slot (Bonus Action), you can roll a d6 per level of the new slot and gain that many Temporary Hit Points. While you have them, a creature that hits you with a melee attack takes Necrotic or Poison damage (your choice) equal to your Charisma modifier. Strengthened Rot: your Sorcerer spells and features ignore Resistance to Necrotic and Poison damage.","Defiled Sorcery|Withering Aura":"When you use Innate Sorcery, a 15-foot Emanation of defiling magic surrounds you while it lasts. Defiling Shroud: when an enemy in the aura hits you with an attack roll, reduce the damage by your Charisma modifier. Essence Siphon: when an enemy in the aura dies, you regain 1d4 Sorcery Points. You can do this once per use of Innate Sorcery.","Defiled Sorcery|Superior Defiler":"Fouled Soul: you have Immunity to the Poisoned and Exhaustion conditions. Furthered Defilement: Withering Aura grows to a 30-foot Emanation, and enemies in it can't regain Hit Points."},"auto":[[3,"Blindness/deafness,Inflict Wounds,Ray of Enfeeblement,Ray of Sickness"],[5,"Bestow Curse,Vampiric Touch"],[7,"Blight,Hallucinatory Terrain"],[9,"Antilife Shell,Contagion"]],"lu":[{"src":"sub","owner":"Defiled Sorcery","feature":"Defile and Empower","n":"Life Steal","lvl":3,"max":1,"reset":"long","tag":"Reset by 3 Sorcery Points"},{"src":"sub","owner":"Defiled Sorcery","feature":"Withering Aura","n":"Essence Siphon","lvl":14,"max":1,"reset":"long","tag":"Per Innate Sorcery"}],"acts":{},"cantrips":[],"pick":[],"fx":[[18,"Superior Defiler",{"condImm":["Poisoned","Exhaustion"]}]],"spab":"CHA"},{"alt":[],"cls":"Fighter","name":"Gladiator","src":"tua24","arr":[[3,"Brutality","Once per turn, when you hit with a Melee weapon attack roll, you can add one Brutality effect. You can do this a number of times equal to your Charisma modifier (min 1), and regain all uses after a Short or Long Rest. Your options are Bleed, Bluff, and Stumble, with more at level 10."],[3,"Combat Theatrics","Athletic Flair: add your Charisma modifier (min +1) to Dexterity (Acrobatics) and Strength (Athletics) checks. Bonus Proficiency: gain one skill from Acrobatics, Athletics, Deception, Intimidation, or Performance."],[3,"Bleed","Brutality effect. Use the Sap mastery property together with a different mastery property of the weapon. The target also takes extra damage equal to your Charisma modifier (min 1), of the weapon's damage type."],[3,"Bluff","Brutality effect. Use the Vex mastery property together with a different mastery property of the weapon. You also have Advantage on the next saving throw you make before the end of your next turn."],[3,"Stumble","Brutality effect. Use the Topple mastery property together with a different mastery property of the weapon. On its next turn the target can take an action or a Bonus Action, not both."],[7,"Flourish Parry","Reaction when an enemy hits you with a melee attack roll: add your Charisma modifier (min +1) to your AC against it, which can turn the hit into a miss. Flourish Counter: if it misses, you can make a Melee weapon attack against that creature as part of the same Reaction. If it hits, apply one Brutality effect without spending a use. After a counterattack hits you can't use it again until a Long Rest, or until you spend a Second Wind use (no action)."],[10,"Bolder Brutalities","You gain three more Brutality options: Rive, Rush, and Stagger."],[10,"Rive","Brutality effect. Use the Cleave mastery property together with a different mastery property of the weapon. You add your ability modifier to the damage of the extra attack."],[10,"Rush","Brutality effect. Use the Push mastery property together with a different mastery property of the weapon. You can then move up to your Speed without provoking Opportunity Attacks."],[10,"Stagger","Brutality effect. Use the Slow mastery property together with a different mastery property of the weapon. The target also has Disadvantage on the next saving throw it makes before the end of your next turn."],[15,"Brutal Resurgence","When you use Second Wind to regain Hit Points, you regain one use of Brutality. You also regain one use when you use Action Surge."],[18,"Mutilate","When you hit a Bloodied creature with an attack roll, you can try to cripple it. It makes a Constitution save (DC 8 + Charisma modifier + Proficiency Bonus). On a failure, until it regains Hit Points: Maimed, so it can make only one attack with the Attack action, and Sluggish, so its Speed is halved and it takes a -2 penalty to AC. After a creature fails against this feature you can't use it again until a Long Rest."]],"full":{"Gladiator|Brutality":"Once per turn, when you hit with a Melee weapon attack roll, you can add one Brutality effect. You can do this a number of times equal to your Charisma modifier (min 1), and regain all uses after a Short or Long Rest. Your options are Bleed, Bluff, and Stumble, with more at level 10.","Gladiator|Combat Theatrics":"Athletic Flair: add your Charisma modifier (min +1) to Dexterity (Acrobatics) and Strength (Athletics) checks. Bonus Proficiency: gain one skill from Acrobatics, Athletics, Deception, Intimidation, or Performance.","Gladiator|Bleed":"Brutality effect. Use the Sap mastery property together with a different mastery property of the weapon. The target also takes extra damage equal to your Charisma modifier (min 1), of the weapon's damage type.","Gladiator|Bluff":"Brutality effect. Use the Vex mastery property together with a different mastery property of the weapon. You also have Advantage on the next saving throw you make before the end of your next turn.","Gladiator|Stumble":"Brutality effect. Use the Topple mastery property together with a different mastery property of the weapon. On its next turn the target can take an action or a Bonus Action, not both.","Gladiator|Flourish Parry":"Reaction when an enemy hits you with a melee attack roll: add your Charisma modifier (min +1) to your AC against it, which can turn the hit into a miss. Flourish Counter: if it misses, you can make a Melee weapon attack against that creature as part of the same Reaction. If it hits, apply one Brutality effect without spending a use. After a counterattack hits you can't use it again until a Long Rest, or until you spend a Second Wind use (no action).","Gladiator|Bolder Brutalities":"You gain three more Brutality options: Rive, Rush, and Stagger.","Gladiator|Rive":"Brutality effect. Use the Cleave mastery property together with a different mastery property of the weapon. You add your ability modifier to the damage of the extra attack.","Gladiator|Rush":"Brutality effect. Use the Push mastery property together with a different mastery property of the weapon. You can then move up to your Speed without provoking Opportunity Attacks.","Gladiator|Stagger":"Brutality effect. Use the Slow mastery property together with a different mastery property of the weapon. The target also has Disadvantage on the next saving throw it makes before the end of your next turn.","Gladiator|Brutal Resurgence":"When you use Second Wind to regain Hit Points, you regain one use of Brutality. You also regain one use when you use Action Surge.","Gladiator|Mutilate":"When you hit a Bloodied creature with an attack roll, you can try to cripple it. It makes a Constitution save (DC 8 + Charisma modifier + Proficiency Bonus). On a failure, until it regains Hit Points: Maimed, so it can make only one attack with the Attack action, and Sluggish, so its Speed is halved and it takes a -2 penalty to AC. After a creature fails against this feature you can't use it again until a Long Rest."},"auto":[],"lu":[{"src":"sub","owner":"Gladiator","feature":"Brutality","n":"Brutality","lvl":3,"max":"mod:CHA","reset":"short","tag":"Once per turn on a Melee hit"},{"src":"sub","owner":"Gladiator","feature":"Flourish Parry","n":"Flourish Counter","lvl":7,"max":1,"reset":"long","tag":"Reset by a Second Wind use"},{"src":"sub","owner":"Gladiator","feature":"Mutilate","n":"Mutilate","lvl":18,"max":1,"reset":"long","tag":"On a Bloodied target"}],"acts":{"sub|Gladiator|Flourish Parry":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[3,"Combat Theatrics",{"skills":["Acrobatics","Athletics"],"notes":[["Note","Athletic Flair: add Charisma modifier (min +1) to Acrobatics and Athletics checks. One more skill from Acrobatics, Athletics, Deception, Intimidation, Performance"]]}],[7,"Flourish Parry",{"notes":[["Note","Flourish Parry (Reaction): add Charisma modifier (min +1) to your AC against one melee hit"]]}]],"spab":""},{"alt":[],"cls":"Warlock","name":"Sorcerer-King Patron","src":"tua24","arr":[[3,"Sorcerer-King Spells","Spells always prepared from the listed Warlock levels: 3 Command, Compelled Duel, Hold Person, Mind Spike, Wrathful Smite. 5 Fear, Sending. 7 Compulsion, Staggering Smite. 9 Dominate Person, Synaptic Static. Psionic Casting: you can cast these spells without Verbal or Material components, unless a Material component is consumed or has a listed cost."],[3,"Tyrant's Herald","Intimidating Presence: gain proficiency and Expertise in Intimidation. Voice of Tyranny: cast Command as a Bonus Action without a spell slot, a number of times equal to your Charisma modifier (min 1), regaining all uses after a Long Rest."],[6,"Decisive Edict","When you cast a spell with a Pact Magic slot, profane power can erupt in a 30-foot Emanation from you. For each creature you see in it, choose Marshal (Advantage on attack rolls until the end of its next turn) or Oppress (Wisdom save against your spell save DC or Frightened until the end of its next turn). After using this you can't use it again until a Short or Long Rest, or when you use Magical Cunning."],[10,"Vindictive Rebuke","Reaction when an enemy hits you with an attack roll: the enemy rerolls the d20 and must use the new roll. If that turns the hit into a miss, it takes Psychic damage equal to your Warlock level. You can do this a number of times equal to your Charisma modifier (min 1), regaining all uses after a Long Rest."],[14,"Absolute Tyranny","When you cast Command you can target one extra creature in range. A creature Frightened by you automatically fails its save against your Command."]],"full":{"Sorcerer-King Patron|Sorcerer-King Spells":"Spells always prepared from the listed Warlock levels: 3 Command, Compelled Duel, Hold Person, Mind Spike, Wrathful Smite. 5 Fear, Sending. 7 Compulsion, Staggering Smite. 9 Dominate Person, Synaptic Static. Psionic Casting: you can cast these spells without Verbal or Material components, unless a Material component is consumed or has a listed cost.","Sorcerer-King Patron|Tyrant's Herald":"Intimidating Presence: gain proficiency and Expertise in Intimidation. Voice of Tyranny: cast Command as a Bonus Action without a spell slot, a number of times equal to your Charisma modifier (min 1), regaining all uses after a Long Rest.","Sorcerer-King Patron|Decisive Edict":"When you cast a spell with a Pact Magic slot, profane power can erupt in a 30-foot Emanation from you. For each creature you see in it, choose Marshal (Advantage on attack rolls until the end of its next turn) or Oppress (Wisdom save against your spell save DC or Frightened until the end of its next turn). After using this you can't use it again until a Short or Long Rest, or when you use Magical Cunning.","Sorcerer-King Patron|Vindictive Rebuke":"Reaction when an enemy hits you with an attack roll: the enemy rerolls the d20 and must use the new roll. If that turns the hit into a miss, it takes Psychic damage equal to your Warlock level. You can do this a number of times equal to your Charisma modifier (min 1), regaining all uses after a Long Rest.","Sorcerer-King Patron|Absolute Tyranny":"When you cast Command you can target one extra creature in range. A creature Frightened by you automatically fails its save against your Command."},"auto":[[3,"Command,Compelled Duel,Hold Person,Mind Spike,Wrathful Smite"],[5,"Fear,Sending"],[7,"Compulsion,Staggering Smite"],[9,"Dominate Person,Synaptic Static"]],"lu":[{"src":"sub","owner":"Sorcerer-King Patron","feature":"Tyrant's Herald","n":"Voice of Tyranny","lvl":3,"max":"mod:CHA","reset":"long","tag":"Bonus Action Command"},{"src":"sub","owner":"Sorcerer-King Patron","feature":"Decisive Edict","n":"Decisive Edict","lvl":6,"max":1,"reset":"short","tag":"On a Pact Magic cast"},{"src":"sub","owner":"Sorcerer-King Patron","feature":"Vindictive Rebuke","n":"Vindictive Rebuke","lvl":10,"max":"mod:CHA","reset":"long","tag":"Reaction"}],"acts":{"sub|Sorcerer-King Patron|Decisive Edict":[["other","","Decisive Edict"]],"sub|Sorcerer-King Patron|Vindictive Rebuke":[["reaction",""]]},"cantrips":[],"pick":[],"fx":[[3,"Tyrant's Herald",{"skills":["Intimidation"],"exp":["Intimidation"]}]],"spab":"CHA"}];
